/// `/etc/fluxbee/hive.yaml`: the hive's own settings. What the release defines for each role (its
/// SY nodes, the blob's and dist's topology) is in `json_router::release_settings`; a file that
/// still holds those keys parses as before, and they are ignored (`warn_superseded_hive_keys`).
/// `ai` is untyped: on the motherbee it is the installation file's first version, typed only when
/// the start writes it, and once a hive holds the file it is ignored (docs/hive-config-update-v1.md
/// §4), so an `ai` no reader uses never stops the start.
#[derive(Debug, Deserialize)]
struct HiveFile {
    hive_id: String,
    role: Option<String>,
    wan: Option<WanSection>,
    storage: Option<StorageSection>,
    blob: Option<BlobSection>,
    dist: Option<DistSection>,
    identity: Option<IdentitySection>,
    government: Option<GovernmentSection>,
    egress: Option<EgressSection>,
    ingress: Option<HiveIngressSection>,
    ai: Option<serde_yaml::Value>,
}

/// The `ingress:` section of an ingress hive's own hive.yaml (docs/control-path-hardening-v1.md
/// §6): the addresses and networks, besides the motherbee, its SSH is accepted from. add_hive
/// writes it when the operator passes `ssh_allow_from`; editing it and restarting the
/// orchestrator is the recovery path.
#[derive(Debug, Default, Deserialize)]
struct HiveIngressSection {
    #[serde(default)]
    ssh_allow_from: Vec<String>,
}

/// Egress NAT parameters. On a `role: egress` hive this carries the LAN/WAN
/// plumbing the orchestrator reconciles into nftables/sysctl. On motherbee only
/// `gateway_ip` (and optionally `edge_hive`) are meaningful: they drive worker
/// default-route injection. See `docs/edge-egress-nat-spec.md`.
#[derive(Debug, Clone, Deserialize)]
struct EgressSection {
    #[serde(default)]
    enabled: bool,
    lan_cidr: Option<String>,
    edge_ip: Option<String>,
    wan_iface: Option<String>,
    lan_iface: Option<String>,
    #[serde(default = "default_ipv6_policy")]
    ipv6: String,
    gateway_ip: Option<String>,
    /// Informational only (Mode A inventory clarity); part of the yaml contract
    /// but not consumed by reconciliation.
    #[allow(dead_code)]
    edge_hive: Option<String>,
    /// The URL the internet probe GETs over HTTPS (docs/acme-edge-certificates-v1.md §8). Each
    /// hive that probes reads its own: the egress, the workers that route through it (add_hive
    /// renders the motherbee's into theirs) and the motherbee. There is no default: without it
    /// the probe does not run, and reports `not_configured`.
    reachability_url: Option<String>,
    /// Whether SSH may arrive on `wan_iface` (docs/control-path-hardening-v1.md §6, D31): the
    /// operator's decision, true by default. False drops it in the egress' `fluxbee_egress` table.
    #[serde(default = "default_ssh_from_wan")]
    ssh_from_wan: bool,
}

fn default_ssh_from_wan() -> bool {
    true
}

impl EgressSection {
    /// The URL this hive's internet probe GETs. `None` when hive.yaml names none, or names one
    /// `validate_reachability_url` refuses (logged): the probe then does not run, and nothing
    /// picks a target in its place.
    fn probe_url(&self) -> Option<String> {
        let url = self
            .reachability_url
            .as_deref()
            .map(str::trim)
            .filter(|url| !url.is_empty())?;
        match validate_reachability_url(url, "egress.reachability_url") {
            Ok(url) => Some(url),
            Err(err) => {
                tracing::warn!(error = %err, "the internet probe does not run");
                None
            }
        }
    }
}

fn default_ipv6_policy() -> String {
    "blocked".to_string()
}

/// Ingress edge-frontend parameters. On a `role: ingress` hive this drives the
/// `SY.edge` public `:443` frontend, written into the remote hive.yaml `edge:`
/// section (sy_edge reads it and, gated on `role==ingress`, binds the door). See
/// docs/edge-ingress-spec-v6.md.
#[derive(Debug, Clone, Deserialize)]
struct IngressSection {
    listen: Option<String>,
    /// SY.vault secret key holding the public TLS material `{cert, key}` (PEM). When
    /// set, it is rendered into the remote `edge:` block so SY.edge fetches its cert
    /// from vault at boot and serves HTTPS fail-closed (spec §8 / blocker H3). The
    /// secret must be seeded (owner_node = `SY.edge@<edge_hive>`) BEFORE the join.
    #[serde(default)]
    tls_vault_key: Option<String>,
    /// Hive whose SY.vault holds the TLS secret. Defaults (at the edge) to `motherbee`.
    #[serde(default)]
    vault_hive: Option<String>,
    /// The add_hive request's `ssh_allow_from` (docs/control-path-hardening-v1.md §6): the
    /// addresses and networks, besides the motherbee, the ingress takes SSH from. The join writes
    /// them into the ingress' hive.yaml as `ingress.ssh_allow_from`.
    #[serde(skip)]
    ssh_allow_from: Vec<SshAllowNet>,
}

/// The add_hive request's `ssh_allow_from`, ingress only: IP addresses or networks. SY.admin passes
/// it through checked; it is parsed again here, since it lands in the ingress' hive.yaml and its
/// nftables rules.
fn resolve_add_hive_ssh_allow_from(
    payload: &serde_json::Value,
) -> Result<Vec<SshAllowNet>, String> {
    match payload.get("ssh_allow_from") {
        None | Some(serde_json::Value::Null) => Ok(Vec::new()),
        Some(serde_json::Value::Array(entries)) => entries
            .iter()
            .map(|entry| {
                let raw = entry.as_str().ok_or(
                    "ssh_allow_from must be an array of IP addresses or networks (strings)",
                )?;
                SshAllowNet::parse(raw).map_err(|err| format!("ssh_allow_from: {err}"))
            })
            .collect(),
        Some(_) => Err("ssh_allow_from must be an array of IP addresses or networks".to_string()),
    }
}

fn resolve_add_hive_ingress_section(
    payload: &serde_json::Value,
) -> Result<IngressSection, OrchestratorError> {
    let ing = payload.get("ingress").and_then(|v| v.as_object()).ok_or(
        "add_hive role=ingress requires an 'ingress' object (listen, optional endpoints_json)",
    )?;
    let get_str = |key: &str| {
        ing.get(key)
            .and_then(|v| v.as_str())
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
    };
    // A public listener must be EXPLICIT — no safe default for a :443 bind.
    let listen = get_str("listen").ok_or(
        "add_hive role=ingress requires 'ingress.listen' (host:port for the public frontend)",
    )?;
    let listen_addr: std::net::SocketAddr = listen.parse().map_err(|_| {
        format!("invalid ingress.listen '{listen}' (want host:port, e.g. 0.0.0.0:443)")
    })?;
    // The scalar is interpolated into the double-quoted hive.yaml `edge:` block —
    // guard against YAML injection at request time (mirrors the egress guard).
    validate_yaml_scalar(&listen, "ingress.listen")?;
    let allow_plaintext = match ing.get("allow_plaintext") {
        Some(value) => value
            .as_bool()
            .ok_or("ingress.allow_plaintext must be boolean")?,
        None => false,
    };
    let tls_vault_key = get_str("tls_vault_key");
    if let Some(key) = tls_vault_key.as_deref() {
        validate_yaml_scalar(key, "ingress.tls_vault_key")?;
    }
    if tls_vault_key.is_none() {
        if !allow_plaintext {
            return Err(
                "add_hive role=ingress requires ingress.tls_vault_key; set ingress.allow_plaintext=true only for explicit dev plaintext"
                    .into(),
            );
        }
        if listen_addr.port() == 443 {
            return Err("ingress.allow_plaintext=true is not allowed on port 443".into());
        }
    }
    if let Some(seed) = ing.get("endpoints_json") {
        if !ingress_endpoints_seed_is_empty(seed) {
            return Err(
                "ingress.endpoints_json is no longer accepted; publish URLs with externalize"
                    .into(),
            );
        }
    }
    let vault_hive = get_str("vault_hive");
    if let Some(hive) = vault_hive.as_deref() {
        validate_yaml_scalar(hive, "ingress.vault_hive")?;
    }
    let ssh_allow_from = resolve_add_hive_ssh_allow_from(payload)?;
    Ok(IngressSection {
        listen: Some(listen),
        tls_vault_key,
        vault_hive,
        ssh_allow_from,
    })
}

fn ingress_endpoints_seed_is_empty(value: &serde_json::Value) -> bool {
    value
        .get("endpoints")
        .and_then(|endpoints| endpoints.as_array())
        .map(|endpoints| endpoints.is_empty())
        .unwrap_or(false)
}

