    /// D32: a request with the removed field is refused before anything starts.
    #[test]
    fn add_hive_refuses_ssh_access_before_the_join_starts() {
        let src = include_str!("sy_orchestrator.rs");
        let start = src
            .find("async fn accept_add_hive(")
            .expect("accept_add_hive");
        let body = &src[start..];
        let refuse = body
            .find("reject_removed_add_hive_fields(payload)")
            .expect("refusal");
        let spawn = body.find("spawn_background_join(").expect("spawn");
        assert!(refuse < spawn);
    }

    #[test]
    fn resolve_add_hive_ssh_creds_requires_user_and_optional_password() {
        // ssh_user + ssh_password both present -> Ok with both.
        let creds = resolve_add_hive_ssh_creds(
            &serde_json::json!({"ssh_user": "admin", "ssh_password": "secret"}),
        )
        .unwrap();
        assert_eq!(creds.user, "admin");
        assert_eq!(creds.password.as_deref(), Some("secret"));

        // ssh_user present, no ssh_password -> Ok, password None.
        let creds = resolve_add_hive_ssh_creds(&serde_json::json!({"ssh_user": "admin"})).unwrap();
        assert_eq!(creds.user, "admin");
        assert!(creds.password.is_none());

        // empty ssh_password is treated as None.
        let creds = resolve_add_hive_ssh_creds(
            &serde_json::json!({"ssh_user": "admin", "ssh_password": "   "}),
        )
        .unwrap();
        assert!(creds.password.is_none());

        // A password with significant surrounding spaces is preserved verbatim
        // (NOT trimmed): trimming would corrupt a legitimate password (review).
        let creds = resolve_add_hive_ssh_creds(
            &serde_json::json!({"ssh_user": "admin", "ssh_password": "  pa ss  "}),
        )
        .unwrap();
        assert_eq!(creds.password.as_deref(), Some("  pa ss  "));

        // ssh_user missing -> Err. ssh_user empty/whitespace -> Err.
        assert!(resolve_add_hive_ssh_creds(&serde_json::json!({})).is_err());
        assert!(resolve_add_hive_ssh_creds(&serde_json::json!({"ssh_user": ""})).is_err());
        assert!(resolve_add_hive_ssh_creds(&serde_json::json!({"ssh_user": "   "})).is_err());
    }

    #[test]
    fn resolve_add_hive_ssh_creds_accepts_and_validates_ssh_key() {
        // A PEM private key is kept VERBATIM (newlines preserved — never trimmed).
        let pem =
            "-----BEGIN OPENSSH PRIVATE KEY-----\nAAAAB3Nz\n-----END OPENSSH PRIVATE KEY-----\n";
        let creds =
            resolve_add_hive_ssh_creds(&serde_json::json!({"ssh_user": "ubuntu", "ssh_key": pem}))
                .unwrap();
        assert_eq!(creds.ssh_key.as_deref(), Some(pem));
        // No ssh_key -> None.
        let creds = resolve_add_hive_ssh_creds(&serde_json::json!({"ssh_user": "ubuntu"})).unwrap();
        assert!(creds.ssh_key.is_none());
        // A non-PEM blob is rejected up front (fails here, not mid-bootstrap).
        assert!(resolve_add_hive_ssh_creds(
            &serde_json::json!({"ssh_user": "ubuntu", "ssh_key": "not-a-key"})
        )
        .is_err());
    }

    #[test]
    fn transient_ssh_errors_are_classified_but_auth_failures_are_not() {
        for t in [
            "ssh: connect to host 10.0.0.2 port 22: Connection refused",
            "Connection reset by peer",
            "client_loop: send disconnect: Broken pipe",
            "ssh: connect to host x port 22: Connection timed out",
        ] {
            assert!(is_transient_ssh_error(t), "should be transient: {t}");
        }
        for permanent in [
            "Permission denied (publickey,password).",
            "sudo: a password is required",
            "write_remote_file via ssh+tee failed (exit=1): stderr=some app error",
        ] {
            assert!(
                !is_transient_ssh_error(permanent),
                "should NOT be transient: {permanent}"
            );
        }
        // add_hive_result_is_transient reads message/error_detail/retryable.
        assert!(add_hive_result_is_transient(&serde_json::json!({
            "message": "ssh: connect to host h port 22: Connection refused"
        })));
        assert!(add_hive_result_is_transient(
            &serde_json::json!({ "retryable": true })
        ));
        assert!(!add_hive_result_is_transient(&serde_json::json!({
            "message": "Permission denied (publickey)"
        })));
    }

    #[test]
    fn node_identity_created_this_attempt_only_for_new_generated_ilk() {
        let register = Some(serde_json::json!({
            "status": "ok",
            "ilk_id": "ilk:11111111-1111-1111-1111-111111111111",
            "requested_ilk_id": "ilk:11111111-1111-1111-1111-111111111111",
        }));
        assert!(node_identity_created_this_attempt(
            &serde_json::json!({}),
            None,
            &register
        ));

        assert!(!node_identity_created_this_attempt(
            &serde_json::json!({}),
            Some("ilk:22222222-2222-2222-2222-222222222222"),
            &register
        ));
        assert!(!node_identity_created_this_attempt(
            &serde_json::json!({"ilk_id": "ilk:11111111-1111-1111-1111-111111111111"}),
            None,
            &register
        ));

        let canonical_existing = Some(serde_json::json!({
            "status": "ok",
            "ilk_id": "ilk:33333333-3333-3333-3333-333333333333",
            "requested_ilk_id": "ilk:11111111-1111-1111-1111-111111111111",
        }));
        assert!(!node_identity_created_this_attempt(
            &serde_json::json!({}),
            None,
            &canonical_existing
        ));
    }

