    #[test]
    fn remove_hive_cleanup_script_cleans_persisted_node_dirs() {
        let script = remove_hive_cleanup_script();
        // A removed ingress's SY.edge must stop: its unit restarts on its own, and it would keep
        // serving `/public/<key>` from its own registry until each page expires (FINDINGS A-236).
        assert!(
            script.contains(" sy-edge "),
            "sy-edge is stopped and disabled"
        );
        assert!(script.contains("/var/lib/fluxbee/nodes/*"));
        assert!(script.contains("/var/lib/fluxbee/state/nodes/*"));
        // The managed nodes stop before their directories go.
        let nodes_stop = script
            .find("systemctl stop 'fluxbee-node-*'")
            .expect("managed nodes stopped");
        assert!(nodes_stop < script.find("rm -rf /var/lib/fluxbee/nodes/*").unwrap());
    }

    /// FINDINGS A-48: the removed box loses its mesh credentials before anything else.
    #[test]
    fn remove_hive_cleanup_takes_the_mesh_credentials_first() {
        for (egress_teardown, ingress_teardown) in [(false, false), (true, false), (false, true)] {
            assert!(
                remove_hive_cleanup_full_script(egress_teardown, ingress_teardown, false)
                    .starts_with(
                    "rm -rf /var/lib/fluxbee/tls /var/lib/fluxbee/identity/keys >/dev/null 2>&1 \
                     || true; "
                )
            );
        }
    }

    /// docs/control-path-hardening-v1.md §6: a removed ingress drops its SSH table and boot unit,
    /// after its services (sy-orchestrator included) are stopped, so nothing loads it again. Every
    /// other role's cleanup leaves no trace of it.
    #[test]
    fn remove_hive_cleanup_drops_the_ingress_ssh_table_last() {
        let worker = remove_hive_cleanup_full_script(false, false, false);
        assert!(!worker.contains("fluxbee_ingress"), "{worker}");
        assert!(!worker.contains("fluxbee-ingress"), "{worker}");
        assert!(!remove_hive_cleanup_full_script(true, false, false).contains("fluxbee_ingress"));

        let ingress = remove_hive_cleanup_full_script(false, true, false);
        assert!(ingress.ends_with(&ingress_teardown_script()), "{ingress}");
        let teardown = ingress_teardown_script();
        assert!(teardown.contains("nft delete table inet fluxbee_ingress"));
        assert!(teardown.contains("systemctl disable fluxbee-ingress-nft.service"));
        assert!(teardown.contains(
            "rm -f /etc/nftables.d/fluxbee-ingress.nft /etc/systemd/system/fluxbee-ingress-nft.service"
        ));
        assert!(teardown.contains("systemctl daemon-reload"));
        // Every step tolerates a host without the table or the unit.
        assert_eq!(
            teardown.matches("|| true").count(),
            teardown.split("; ").count()
        );
        let stop = ingress.find("sy-orchestrator").expect("the services stop");
        assert!(
            stop < ingress
                .find("nft delete table inet fluxbee_ingress")
                .unwrap()
        );
        assert!(!ingress.contains("fluxbee_egress"));

        // The spoke decides by its own role.
        let src = include_str!("sy_orchestrator.rs");
        let arm = &src[src
            .find("Some(\"REMOVE_HIVE_CLEANUP\") => {")
            .expect("the arm")..];
        let arm = &arm[..arm.find("send_system_action_response").expect("its answer")];
        assert!(arm.contains("state.role == HiveRole::Ingress"), "{arm}");
    }

    /// The cleanup stops sy-orchestrator, so it runs in a transient unit of its own, never as the
    /// orchestrator's child: the whole script runs to its end.
    #[test]
    fn remove_hive_cleanup_runs_in_its_own_transient_unit() {
        let cmd = remove_hive_cleanup_command("fluxbee-remove-hive-cleanup-1", true, false, false);
        assert_eq!(cmd.get_program(), "systemd-run");
        let args: Vec<String> = cmd
            .get_args()
            .map(|arg| arg.to_string_lossy().to_string())
            .collect();
        assert_eq!(
            args[..6],
            [
                "--on-active=1s",
                "--timer-property=AccuracySec=100ms",
                "--unit=fluxbee-remove-hive-cleanup-1",
                "--collect",
                "bash",
                "-c"
            ]
        );
        assert_eq!(args[6], remove_hive_cleanup_full_script(true, false, false));
        assert_eq!(args.len(), 7);
    }

    /// FINDINGS A-48: the registry is the authority on which hives exist. The boot sweep deletes
    /// only `<hive>.key` files whose hive has no directory; remove_hive deletes the hive's key once
    /// its directory is gone, and restarts sy-identity only for a box the cleanup did not reach.
    #[test]
    fn identity_keys_follow_the_hive_registry() {
        let names =
            |names: &[&str]| -> Vec<String> { names.iter().map(|name| name.to_string()).collect() };
        assert_eq!(
            orphan_identity_key_files(
                &names(&[
                    "worker1.key",
                    "worker2.key",
                    "ingress1.key",
                    "notes.txt",
                    "..key"
                ]),
                &names(&["worker1", "ingress1", "egress1"]),
            ),
            Ok(names(&["worker2.key"]))
        );
        assert_eq!(
            orphan_identity_key_files(&names(&["worker1.key"]), &names(&["worker1"])),
            Ok(Vec::new())
        );
        assert_eq!(
            orphan_identity_key_files(&[], &names(&["worker1"])),
            Ok(Vec::new())
        );
        // A registry restored or wiped deletes nothing: an operator decides.
        let empty = orphan_identity_key_files(&names(&["worker1.key"]), &[]).unwrap_err();
        assert!(empty.contains("registry is empty"), "{empty}");
        let every = orphan_identity_key_files(
            &names(&["worker1.key", "worker2.key"]),
            &names(&["ingress1"]),
        )
        .unwrap_err();
        assert!(every.contains("every key would go"), "{every}");

        let dir = std::env::temp_dir().join(format!("fluxbee-identity-keys-{}", Uuid::new_v4()));
        fs::create_dir_all(&dir).expect("dir");
        let key = dir.join("worker2.key");
        fs::write(&key, "00").expect("key");
        assert!(remove_identity_key_file(&key).expect("delete"));
        assert!(!key.exists());
        assert!(!remove_identity_key_file(&key).expect("already gone"));
        let _ = fs::remove_dir_all(&dir);

        let src = include_str!("sy_orchestrator.rs");
        let start = src
            .find("async fn remove_hive_flow(")
            .expect("remove_hive_flow");
        let body = &src[start..start + src[start..].find("\n}\n").expect("its end")];
        let registry = body
            .find("fs::remove_dir_all(dir)")
            .expect("registry removal");
        let key = body
            .find("remove_identity_key_file(")
            .expect("key deletion");
        let call: String = body[key..].split_whitespace().collect();
        assert!(
            call.starts_with("remove_identity_key_file(&json_router::mesh_hmac::key_path(hive_id)"),
            "remove_hive deletes the removed hive's own key"
        );
        let restart = body
            .find("if !identity_key_deleted || socket_cleanup_ok")
            .expect("restart only for a box the cleanup did not reach");
        assert!(registry < key && key < restart);
    }

    #[test]
    fn f11_remove_hive_cleanup_appends_egress_teardown_only_for_egress() {
        // Non-egress (worker) removal: NO NAT teardown, only the base cleanup.
        let worker = remove_hive_cleanup_full_script(false, false, false);
        assert!(worker.contains("/var/lib/fluxbee/nodes/*"));
        assert!(!worker.contains("fluxbee_egress"));
        assert!(!worker.contains("99-fluxbee-egress"));
        assert!(!worker.contains("sysctl --system"));

        // Egress removal: base cleanup PLUS idempotent NAT teardown of the live
        // nft table + all four persistent /etc files + a sysctl reload.
        let egress = remove_hive_cleanup_full_script(true, false, false);
        assert!(egress.contains("/var/lib/fluxbee/nodes/*")); // base preserved
        assert!(egress.contains("nft delete table inet fluxbee_egress"));
        assert!(egress.contains("/etc/nftables.d/fluxbee-egress.nft"));
        assert!(egress.contains("/etc/sysctl.d/99-fluxbee-egress.conf"));
        assert!(egress.contains("/etc/sysctl.d/99-fluxbee-conntrack.conf"));
        assert!(egress.contains("/etc/modprobe.d/fluxbee-conntrack.conf"));
        assert!(egress.contains("sysctl --system"));
        // F17 boot unit is also disabled + removed: no enabled orphan unit (even
        // a no-op one) survives the egress decommission.
        assert!(egress.contains("systemctl disable fluxbee-egress-nft.service"));
        assert!(egress.contains("/etc/systemd/system/fluxbee-egress-nft.service"));
        assert!(egress.contains("systemctl daemon-reload"));
        // Worker (non-egress) removal must NOT touch the boot unit.
        assert!(!worker.contains("fluxbee-egress-nft.service"));
        // Every teardown command is guarded so a non-egress box is a no-op.
        assert!(egress.contains("|| true"));
        // The boundary closes first: the NAT teardown runs right after the mesh
        // credentials, before the services stop.
        let nft_at = egress
            .find("nft delete table")
            .expect("nft teardown present");
        let kill_at = egress
            .find("systemctl kill")
            .expect("base service kill present");
        assert!(
            nft_at < kill_at,
            "the egress teardown runs before the services stop"
        );
    }

