    /// Motherbee serves every spoke role: one core folder per role, pointing at the
    /// materialized per-role subtree, plus the shared vendor folder and the worker-only
    /// runtimes folder. All sendonly — motherbee publishes, it never accepts remote edits.
    #[test]
    fn reconcile_syncthing_folders_declares_per_role_dist_on_motherbee() {
        let config = sample_syncthing_config_with_peer();
        let blob = sample_blob_config();
        let dist = sample_dist_config();

        let (updated, changed_folders) =
            reconcile_syncthing_folders_xml(&config, &blob, &dist, true, HiveRole::Motherbee)
                .expect("folder reconcile must succeed");

        for role in ["worker", "ingress", "egress"] {
            let id = format!("{SYNCTHING_FOLDER_DIST_CORE_PREFIX}{role}");
            assert!(
                changed_folders.contains(&id),
                "motherbee must declare the core folder for role {role}"
            );
            assert!(updated.contains(&format!(
                "<folder id=\"{id}\" label=\"Fluxbee Dist Core\" path=\"/var/lib/fluxbee/dist/core/{role}\" type=\"sendonly\""
            )));
        }
        assert!(changed_folders.contains(&SYNCTHING_FOLDER_DIST_VENDOR_ID.to_string()));
        assert!(changed_folders.contains(&SYNCTHING_FOLDER_DIST_RUNTIMES_ID.to_string()));
    }

    /// A spoke declares only its own role's core folder, mapped onto its plain `dist/core` —
    /// which is why no path constant had to change on the receiving side.
    #[test]
    fn reconcile_syncthing_folders_declares_only_own_role_on_spoke() {
        let config = sample_syncthing_config_with_peer();
        let blob = sample_blob_config();
        let dist = sample_dist_config();

        let (updated, changed_folders) =
            reconcile_syncthing_folders_xml(&config, &blob, &dist, false, HiveRole::Ingress)
                .expect("folder reconcile must succeed");

        assert!(updated.contains(
            "<folder id=\"fluxbee-dist-core-ingress\" label=\"Fluxbee Dist Core\" path=\"/var/lib/fluxbee/dist/core\" type=\"receiveonly\""
        ));
        assert!(!changed_folders
            .iter()
            .any(|f| f == "fluxbee-dist-core-worker"));
    }

    /// The whole point of the split: tenant workflow packages live in `runtimes/`, and the DMZ
    /// door must never receive them. Vendor, by contrast, is mandatory everywhere — without it
    /// `update category=vendor` can never be satisfied and the hive's syncthing freezes.
    #[test]
    fn ingress_and_egress_get_core_and_vendor_but_never_runtimes() {
        let dist = sample_dist_config();
        let blob_root = sample_blob_config().path;
        for role in [HiveRole::Ingress, HiveRole::Egress] {
            let ids: Vec<String> = dist_sync_folders_for_role(&dist, &blob_root, role, true)
                .into_iter()
                .map(|f| f.id)
                .collect();
            assert!(ids.contains(&format!(
                "{SYNCTHING_FOLDER_DIST_CORE_PREFIX}{}",
                role.as_str()
            )));
            assert!(ids.contains(&SYNCTHING_FOLDER_DIST_VENDOR_ID.to_string()));
            assert!(
                !ids.contains(&SYNCTHING_FOLDER_DIST_RUNTIMES_ID.to_string()),
                "{} must never peer the runtimes subtree",
                role.as_str()
            );
            assert!(
                !ids.contains(&SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID.to_string()),
                "{} runs no agent",
                role.as_str()
            );
        }
        // The worker does get it — it is the ONLY delivery path for published packages
        // (there is no sync_runtime_to_worker SSH push) — and the agent assets its agents read
        // (FINDINGS A-72), from blob/agent-assets on both ends.
        for is_motherbee in [true, false] {
            let worker =
                dist_sync_folders_for_role(&dist, &blob_root, HiveRole::Worker, is_motherbee);
            assert!(worker
                .iter()
                .any(|f| f.id == SYNCTHING_FOLDER_DIST_RUNTIMES_ID));
            let assets: Vec<&DistSyncFolder> = worker
                .iter()
                .filter(|f| f.id == SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID)
                .collect();
            assert_eq!(assets.len(), 1);
            assert_eq!(assets[0].path, blob_root.join("agent-assets"));
        }
    }

    /// The global user OPA policy reaches EVERY hive (ingress and egress route with it too), on
    /// the same `dist/policy` path at both ends: motherbee sends, the spoke receives.
    #[test]
    fn every_role_gets_the_policy_folder() {
        let dist = sample_dist_config();
        let blob_root = sample_blob_config().path;
        for role in [HiveRole::Worker, HiveRole::Ingress, HiveRole::Egress] {
            for is_motherbee in [true, false] {
                let policy: Vec<DistSyncFolder> =
                    dist_sync_folders_for_role(&dist, &blob_root, role, is_motherbee)
                        .into_iter()
                        .filter(|f| f.id == SYNCTHING_FOLDER_DIST_POLICY_ID)
                        .collect();
                assert_eq!(
                    policy.len(),
                    1,
                    "{} (motherbee side: {is_motherbee})",
                    role.as_str()
                );
                assert_eq!(policy[0].path, dist.path.join("policy"));
            }
        }
    }

    /// A hive that joined before the policy folder existed gets it shared with the peers it
    /// already shares vendor with — both ends, on the next local reconcile, without a re-join.
    /// Only policy follows vendor: runtimes stays off a peer that never had it (the ingress).
    #[test]
    fn policy_folder_reaches_the_peers_that_joined_before_it() {
        let dist = sample_dist_config();
        let mut blob = sample_blob_config();
        blob.public_sync_enabled = false;
        let joined_before = format!(
            "<configuration version=\"37\">
  <device id=\"{local}\" name=\"sandbox\"></device>
  <device id=\"{peer}\" name=\"ingress-1\"></device>
  <folder id=\"{vendor}\" label=\"Fluxbee Dist Vendor\" path=\"/var/lib/fluxbee/dist/vendor\" type=\"sendonly\">
    <device id=\"{local}\" introducedBy=\"\"/>
    <device id=\"{peer}\" introducedBy=\"\"/>
  </folder>
</configuration>",
            local = LOCAL_DEVICE_ID,
            peer = PEER_DEVICE_ID,
            vendor = SYNCTHING_FOLDER_DIST_VENDOR_ID,
        );
        for (is_motherbee, role) in [(true, HiveRole::Motherbee), (false, HiveRole::Ingress)] {
            let (updated, changed) =
                reconcile_syncthing_folders_xml(&joined_before, &blob, &dist, is_motherbee, role)
                    .expect("folder reconcile must succeed");
            assert!(changed.contains(&SYNCTHING_FOLDER_DIST_POLICY_ID.to_string()));
            assert_eq!(
                syncthing_folder_device_ids(&updated, SYNCTHING_FOLDER_DIST_POLICY_ID).unwrap(),
                vec![LOCAL_DEVICE_ID.to_string(), PEER_DEVICE_ID.to_string()],
                "motherbee side: {is_motherbee}"
            );
            if is_motherbee {
                // Created with no member (Syncthing adds the local device itself); the peer that
                // never had runtimes does not get it.
                assert!(updated.contains(&format!(
                    "<folder id=\"{SYNCTHING_FOLDER_DIST_RUNTIMES_ID}\""
                )));
                assert!(
                    syncthing_folder_device_ids(&updated, SYNCTHING_FOLDER_DIST_RUNTIMES_ID)
                        .unwrap()
                        .is_empty()
                );
            }
            let (again, changed_again) =
                reconcile_syncthing_folders_xml(&updated, &blob, &dist, is_motherbee, role)
                    .expect("second reconcile must succeed");
            assert!(
                changed_again.is_empty(),
                "not idempotent: {changed_again:?}"
            );
            assert_eq!(again, updated);
        }
    }

    /// FINDINGS A-72: a worker that joined before the agent-assets folder existed gets it with
    /// its next core update, on both ends, shared with the peers it already shares runtimes with;
    /// a peer without runtimes (the ingress) never gets it.
    #[test]
    fn agent_assets_reach_the_workers_that_joined_before_them() {
        const INGRESS: &str = "INGRESS-DEVICE-ID-1234567890";
        let dist = sample_dist_config();
        let mut blob = sample_blob_config();
        blob.public_sync_enabled = false;
        let joined_before = format!(
            "<configuration version=\"37\">
  <device id=\"{local}\" name=\"sandbox\"></device>
  <device id=\"{peer}\" name=\"worker-1\"></device>
  <device id=\"{ingress}\" name=\"ingress-1\"></device>
  <folder id=\"{vendor}\" label=\"Fluxbee Dist Vendor\" path=\"/var/lib/fluxbee/dist/vendor\" type=\"sendonly\">
    <device id=\"{local}\" introducedBy=\"\"/>
    <device id=\"{peer}\" introducedBy=\"\"/>
    <device id=\"{ingress}\" introducedBy=\"\"/>
  </folder>
  <folder id=\"{runtimes}\" label=\"Fluxbee Dist Runtimes\" path=\"/var/lib/fluxbee/dist/runtimes\" type=\"sendonly\">
    <device id=\"{local}\" introducedBy=\"\"/>
    <device id=\"{peer}\" introducedBy=\"\"/>
  </folder>
</configuration>",
            local = LOCAL_DEVICE_ID,
            peer = PEER_DEVICE_ID,
            ingress = INGRESS,
            vendor = SYNCTHING_FOLDER_DIST_VENDOR_ID,
            runtimes = SYNCTHING_FOLDER_DIST_RUNTIMES_ID,
        );
        for (is_motherbee, role) in [(true, HiveRole::Motherbee), (false, HiveRole::Worker)] {
            let (updated, changed) =
                reconcile_syncthing_folders_xml(&joined_before, &blob, &dist, is_motherbee, role)
                    .expect("folder reconcile must succeed");
            assert!(changed.contains(&SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID.to_string()));
            assert!(updated.contains(&format!(
                "<folder id=\"{SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID}\" label=\"Fluxbee Dist Agent Assets\" path=\"/var/lib/fluxbee/blob/agent-assets\" type=\"{}\"",
                dist_syncthing_folder_type(is_motherbee)
            )));
            assert_eq!(
                syncthing_folder_device_ids(&updated, SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID)
                    .unwrap(),
                vec![LOCAL_DEVICE_ID.to_string(), PEER_DEVICE_ID.to_string()],
                "motherbee side: {is_motherbee}"
            );
            let (again, changed_again) =
                reconcile_syncthing_folders_xml(&updated, &blob, &dist, is_motherbee, role)
                    .expect("second reconcile must succeed");
            assert!(
                changed_again.is_empty(),
                "not idempotent: {changed_again:?}"
            );
            assert_eq!(again, updated);
        }
        // An ingress declares no such folder, whoever its peers are.
        let (ingress, _) =
            reconcile_syncthing_folders_xml(&joined_before, &blob, &dist, false, HiveRole::Ingress)
                .expect("folder reconcile must succeed");
        assert!(!ingress.contains(&format!(
            "<folder id=\"{SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID}\""
        )));
    }

    // --- The installation file (docs/hive-config-update-v1.md §4, stage 3b) ---

    /// Every role gets the installation file's folder, on `dist/installation` where the SDK places
    /// the file: send-only on the motherbee, receive-only on every spoke, and never one a role is
    /// taken out of.
    #[test]
    fn every_role_gets_the_installation_folder_send_only_from_the_motherbee() {
        let dist = sample_dist_config();
        let blob = sample_blob_config();
        assert_eq!(
            installation_dist_dir(&dist.path),
            PathBuf::from("/var/lib/fluxbee/dist/installation")
        );
        assert_eq!(
            installation_file_path(&dist.path).parent(),
            Some(installation_dist_dir(&dist.path).as_path())
        );
        for role in [HiveRole::Worker, HiveRole::Ingress, HiveRole::Egress] {
            for is_motherbee in [true, false] {
                let folders: Vec<DistSyncFolder> =
                    dist_sync_folders_for_role(&dist, &blob.path, role, is_motherbee)
                        .into_iter()
                        .filter(|f| f.id == SYNCTHING_FOLDER_DIST_INSTALLATION_ID)
                        .collect();
                assert_eq!(folders.len(), 1, "{} ({is_motherbee})", role.as_str());
                assert_eq!(folders[0].path, dist.path.join("installation"));
            }
            assert!(!folder_forbidden_for_role(
                SYNCTHING_FOLDER_DIST_INSTALLATION_ID,
                role
            ));
        }
        let declared = |is_motherbee: bool, role: HiveRole| {
            reconcile_syncthing_folders_xml(
                &sample_syncthing_config_with_peer(),
                &blob,
                &dist,
                is_motherbee,
                role,
            )
            .expect("folder reconcile must succeed")
        };
        let (motherbee, changed) = declared(true, HiveRole::Motherbee);
        assert!(changed.contains(&SYNCTHING_FOLDER_DIST_INSTALLATION_ID.to_string()));
        assert!(motherbee.contains(
            "<folder id=\"fluxbee-dist-installation\" label=\"Fluxbee Dist Installation\" path=\"/var/lib/fluxbee/dist/installation\" type=\"sendonly\""
        ));
        for role in [HiveRole::Worker, HiveRole::Ingress, HiveRole::Egress] {
            let (spoke, _) = declared(false, role);
            assert!(
                spoke.contains(
                    "<folder id=\"fluxbee-dist-installation\" label=\"Fluxbee Dist Installation\" path=\"/var/lib/fluxbee/dist/installation\" type=\"receiveonly\""
                ),
                "{}",
                role.as_str()
            );
        }
    }

    /// A hive that joined before the installation folder existed gets it shared with the peers it
    /// shares vendor with, on both ends, at the next start of each side's orchestrator: no re-join.
    /// Its join links it like any dist folder, and its removal unlinks it.
    #[test]
    fn the_installation_folder_follows_vendor_s_members_and_leaves_with_the_hive() {
        let dist = sample_dist_config();
        let mut blob = sample_blob_config();
        blob.public_sync_enabled = false;
        let joined_before = format!(
            "<configuration version=\"37\">
  <device id=\"{local}\" name=\"sandbox\"></device>
  <device id=\"{peer}\" name=\"egress-1\"></device>
  <folder id=\"{vendor}\" label=\"Fluxbee Dist Vendor\" path=\"/var/lib/fluxbee/dist/vendor\" type=\"sendonly\">
    <device id=\"{local}\" introducedBy=\"\"/>
    <device id=\"{peer}\" introducedBy=\"\"/>
  </folder>
</configuration>",
            local = LOCAL_DEVICE_ID,
            peer = PEER_DEVICE_ID,
            vendor = SYNCTHING_FOLDER_DIST_VENDOR_ID,
        );
        for (is_motherbee, role) in [
            (true, HiveRole::Motherbee),
            (false, HiveRole::Worker),
            (false, HiveRole::Ingress),
            (false, HiveRole::Egress),
        ] {
            let (updated, changed) =
                reconcile_syncthing_folders_xml(&joined_before, &blob, &dist, is_motherbee, role)
                    .expect("folder reconcile must succeed");
            assert!(changed.contains(&SYNCTHING_FOLDER_DIST_INSTALLATION_ID.to_string()));
            assert_eq!(
                syncthing_folder_device_ids(&updated, SYNCTHING_FOLDER_DIST_INSTALLATION_ID)
                    .unwrap(),
                vec![LOCAL_DEVICE_ID.to_string(), PEER_DEVICE_ID.to_string()],
                "{} (motherbee side: {is_motherbee})",
                role.as_str()
            );
            let (again, changed_again) =
                reconcile_syncthing_folders_xml(&updated, &blob, &dist, is_motherbee, role)
                    .expect("second reconcile must succeed");
            assert!(
                changed_again.is_empty(),
                "not idempotent: {changed_again:?}"
            );
            assert_eq!(again, updated);

            // remove_hive unlinks it with every other dist folder.
            let (removed, removal_changed) =
                reconcile_syncthing_peer_removal_xml(&updated, &blob, &dist, PEER_DEVICE_ID)
                    .expect("peer removal must succeed");
            assert!(removal_changed);
            assert_eq!(
                syncthing_folder_device_ids(&removed, SYNCTHING_FOLDER_DIST_INSTALLATION_ID)
                    .unwrap(),
                vec![LOCAL_DEVICE_ID.to_string()]
            );
        }

        // A join links the new peer to it, on the motherbee's side for every role.
        const SPOKE: &str = "SPOKE-DEVICE-ID-1234567890";
        for role in [HiveRole::Worker, HiveRole::Ingress, HiveRole::Egress] {
            let (linked, _) = reconcile_syncthing_peer_xml(
                &sample_syncthing_config_with_peer(),
                &blob,
                &dist,
                SPOKE,
                "spoke-1",
                SyncthingPeerAddress::AcceptOnly,
                true,
                role,
            )
            .expect("peer link must succeed");
            assert!(
                syncthing_folder_device_ids(&linked, SYNCTHING_FOLDER_DIST_INSTALLATION_ID)
                    .unwrap()
                    .contains(&SPOKE.to_string()),
                "{}",
                role.as_str()
            );
        }
    }

    fn installation_temp_root(tag: &str) -> PathBuf {
        let root = std::env::temp_dir().join(format!(
            "fbinst-{tag}-{}",
            &Uuid::new_v4().simple().to_string()[..8]
        ));
        fs::create_dir_all(&root).expect("temp root");
        root
    }

    fn installation_yaml(text: &str) -> serde_yaml::Value {
        serde_yaml::from_str(text).expect("yaml")
    }

    /// The motherbee's start writes the installation file's first version from its hive.yaml's
    /// `ai`, mode 0644, recorded with its hash, when and why; once the file is there it never
    /// writes it again, whatever hive.yaml says.
    #[test]
    fn the_motherbee_writes_version_1_from_hive_yaml_s_ai_once() {
        let root = installation_temp_root("migrate");
        let dist = root.join("dist");
        let file = installation_file_path(&dist);
        let records = root.join("orchestrator").join("installation-versions.json");
        let ai = installation_yaml(
            "default_provider: anthropic\nproviders:\n  openai:\n    model: gpt-5.5\n  anthropic:\n    model: claude-sonnet-5-5\n",
        );

        let written = write_installation_file_first_version(&file, &records, Some(&ai), 1234)
            .expect("written");
        let bytes = fs::read(&file).expect("the file");
        let sha256 = sha256_hex(&bytes);
        assert_eq!(
            written,
            InstallationMigration::Written {
                sha256: sha256.clone()
            }
        );
        let parsed = InstallationFile::parse(&bytes).expect("a file every reader can use");
        assert_eq!(parsed.version, 1);
        assert_eq!(
            parsed.ai,
            Some(serde_yaml::from_value::<fluxbee_ai_sdk::HiveAiConfig>(ai.clone()).expect("ai"))
        );
        assert_eq!(
            fs::metadata(&file).expect("meta").permissions().mode() & 0o777,
            0o644
        );
        let recorded = read_installation_versions(&records).expect("records");
        assert_eq!(
            recorded.versions,
            vec![InstallationVersionRecord {
                version: 1,
                sha256: sha256.clone(),
                written_at_ms: 1234,
                source: "migration".to_string(),
                // Stage 3c: the version's values, so a later one can put them back.
                ai: parsed.ai.clone(),
            }]
        );
        assert_eq!(
            installation_motherbee_state(&InstallationCopy::read(&dist), Ok(&recorded)),
            "current"
        );

        // There already: nothing written, whatever hive.yaml's ai is now.
        let other = installation_yaml(
            "default_provider: openai\nproviders:\n  openai:\n    model: gpt-5.5\n",
        );
        assert_eq!(
            write_installation_file_first_version(&file, &records, Some(&other), 5678),
            Ok(InstallationMigration::Present)
        );
        assert_eq!(fs::read(&file).expect("the file"), bytes);
        assert_eq!(
            read_installation_versions(&records).expect("records"),
            recorded
        );
        let _ = fs::remove_dir_all(&root);
    }

    /// No `ai` gives a file without one (the fallback engine, as a hive.yaml without one); an `ai`
    /// no reader can use writes nothing and records nothing, and the start says why; a file
    /// missing after a later version was recorded is not written again as version 1.
    #[test]
    fn the_first_version_has_no_ai_without_one_and_none_is_written_from_an_invalid_one() {
        let root = installation_temp_root("noai");
        let file = installation_file_path(&root.join("dist"));
        let records = root.join("installation-versions.json");
        assert!(matches!(
            write_installation_file_first_version(&file, &records, None, 1),
            Ok(InstallationMigration::Written { .. })
        ));
        let bytes = fs::read(&file).expect("the file");
        assert_eq!(InstallationFile::parse(&bytes).expect("parses").ai, None);
        assert!(!String::from_utf8_lossy(&bytes).contains("\"ai\""));
        let _ = fs::remove_dir_all(&root);

        for invalid in [
            "default_provider: gemini\n",
            "default_provider: anthropic\nproviders:\n  openai:\n    model: gpt-5.5\n",
            "default_provider: openai\nproviders:\n  openai:\n    model: \" \"\n",
            "default_provider: openai\nproviders:\n  openai:\n    model: gpt-5.5\n  anthropic:\n    model: \"\"\n",
        ] {
            let root = installation_temp_root("invalid");
            let file = installation_file_path(&root.join("dist"));
            let records = root.join("installation-versions.json");
            let reason = write_installation_file_first_version(
                &file,
                &records,
                Some(&installation_yaml(invalid)),
                1,
            )
            .expect_err(invalid);
            assert!(
                reason.starts_with("hive.yaml's ai is not one every reader can use"),
                "{reason}"
            );
            assert!(!reason.contains("protocol error"), "{reason}");
            assert!(!file.exists(), "{invalid}");
            assert!(!records.exists(), "{invalid}");
            assert_eq!(
                write_installation_file_at_start(
                    &file,
                    &records,
                    Some(&installation_yaml(invalid))
                ),
                Some(reason)
            );
            let _ = fs::remove_dir_all(&root);
        }

        let root = installation_temp_root("later");
        let file = installation_file_path(&root.join("dist"));
        let records = root.join("installation-versions.json");
        let mut later = InstallationVersions::default();
        for version in [1, 2] {
            later.upsert(InstallationVersionRecord {
                version,
                sha256: format!("{version:064}"),
                written_at_ms: version,
                source: "migration".to_string(),
                ai: None,
            });
        }
        write_installation_versions(&records, &later).expect("records");
        let reason =
            write_installation_file_first_version(&file, &records, None, 1).expect_err("later");
        assert!(reason.contains("version 2"), "{reason}");
        assert!(!file.exists());
        let _ = fs::remove_dir_all(&root);
    }

    /// What a hive holds at the installation file's place, for its `/versions`; and the line a
    /// start logs for the `ai` its hive.yaml still holds once the hive holds a file.
    #[test]
    fn each_hive_reports_its_own_copy_and_names_hive_yaml_s_ignored_ai() {
        let root = installation_temp_root("copy");
        let dist = root.join("dist");
        let file = installation_file_path(&dist);
        let absent = InstallationCopy::read(&dist);
        assert_eq!(absent.file, InstallationCopyFile::Absent);
        assert_eq!(
            absent.to_json(),
            serde_json::json!({"file": "absent", "version": null, "sha256": null})
        );
        assert!(ignored_hive_ai_warning(&InstallationFileState::Absent, true).is_none());

        write_installation_file_first_version(&file, &root.join("records.json"), None, 1)
            .expect("written");
        let bytes = fs::read(&file).expect("the file");
        let valid = InstallationCopy::read(&dist);
        // A file without ai holds the fallback engine's values (stage 3c).
        assert_eq!(
            valid.to_json(),
            serde_json::json!({
                "file": "valid",
                "version": 1,
                "sha256": sha256_hex(&bytes),
                "ai": {"default_provider": "openai", "providers": {"openai": {"model": "gpt-5.5"}, "anthropic": null}},
            })
        );
        assert_eq!(InstallationCopy::from_json(&valid.to_json()), Some(valid));
        let state = installation_file_state(&file).expect("state");
        let warning = ignored_hive_ai_warning(&state, true).expect("named");
        assert!(warning.contains("version 1"), "{warning}");
        assert!(warning.contains("ignored"), "{warning}");
        assert!(ignored_hive_ai_warning(&state, false).is_none());

        fs::write(&file, b"{\"schema_version\":1,\"version\":0}").expect("edited");
        let invalid = InstallationCopy::read(&dist);
        assert_eq!(invalid.file, InstallationCopyFile::Invalid);
        assert_eq!(
            invalid.sha256.as_deref(),
            Some(sha256_hex(b"{\"schema_version\":1,\"version\":0}").as_str())
        );
        assert!(invalid
            .error
            .as_deref()
            .is_some_and(|e| e.contains("version 0")));
        let state = installation_file_state(&file).expect("state");
        assert!(ignored_hive_ai_warning(&state, true).is_some());
        let _ = fs::remove_dir_all(&root);

        // An `ai` no reader can use never stops the orchestrator's start.
        let hive: HiveFile = serde_yaml::from_str(
            "hive_id: worker1\nrole: worker\nai:\n  default_provider: gemini\n  providers: 7\n",
        )
        .expect("hive.yaml still loads");
        assert!(hive.ai.is_some());
    }

    /// `/versions`' `config`: the motherbee's own file against the versions it recorded, and each
    /// spoke's copy against the motherbee's file.
    #[test]
    fn versions_judge_each_copy_against_the_motherbee_s_file() {
        let record = |version: u64, sha256: &str| InstallationVersionRecord {
            version,
            sha256: sha256.to_string(),
            written_at_ms: version,
            source: "migration".to_string(),
            ai: None,
        };
        let records = InstallationVersions {
            versions: vec![record(1, "aaa"), record(2, "bbb")],
        };
        let copy = |file: InstallationCopyFile, version: Option<u64>, sha256: Option<&str>| {
            InstallationCopy {
                file,
                version,
                sha256: sha256.map(str::to_string),
                error: None,
                ai: None,
            }
        };
        use InstallationCopyFile::{Absent, Invalid, Valid};
        let unreadable = "unreadable".to_string();

        let motherbee = copy(Valid, Some(2), Some("bbb"));
        for (own, expected) in [
            (motherbee.clone(), "current"),
            (copy(Valid, Some(2), Some("ccc")), "edited_by_hand"),
            (copy(Valid, Some(3), Some("ddd")), "edited_by_hand"),
            (copy(Invalid, None, Some("eee")), "edited_by_hand"),
            (copy(Absent, None, None), "pending"),
        ] {
            assert_eq!(
                installation_motherbee_state(&own, Ok(&records)),
                expected,
                "{own:?}"
            );
        }
        assert_eq!(
            installation_motherbee_state(&motherbee, Err(&unreadable)),
            "unknown"
        );

        for (spoke, expected) in [
            (copy(Valid, Some(2), Some("bbb")), "current"),
            (copy(Valid, Some(1), Some("aaa")), "behind"),
            (copy(Absent, None, None), "pending"),
            (copy(Valid, Some(1), Some("fff")), "edited_by_hand"),
            (copy(Invalid, None, Some("aaa")), "edited_by_hand"),
            (copy(Invalid, None, None), "edited_by_hand"),
        ] {
            assert_eq!(
                installation_spoke_state(&spoke, &motherbee, Ok(&records)),
                expected,
                "{spoke:?}"
            );
        }
        assert_eq!(
            installation_spoke_state(
                &copy(Valid, Some(1), Some("aaa")),
                &motherbee,
                Err(&unreadable)
            ),
            "unknown"
        );
        // A motherbee that holds no file has nothing a copy can match.
        assert_eq!(
            installation_spoke_state(
                &copy(Valid, Some(1), Some("aaa")),
                &copy(Absent, None, None),
                Ok(&records)
            ),
            "behind"
        );

        // A spoke's answer gets its state; an older orchestrator's, without config, is left as is.
        let mut answer = serde_json::json!({
            "status": "ok",
            "hive": {"hive_id": "worker1", "config": copy(Valid, Some(1), Some("aaa")).to_json()},
        });
        add_installation_state_to_answer(&mut answer, &motherbee, &Ok(records.clone()));
        assert_eq!(
            answer["hive"]["config"]["state"],
            serde_json::json!("behind")
        );
        let mut older = serde_json::json!({"status": "ok", "hive": {"hive_id": "egress1"}});
        add_installation_state_to_answer(&mut older, &motherbee, &Ok(records.clone()));
        assert!(older["hive"].get("config").is_none());

        // The motherbee's own section: its state, and why its start wrote nothing.
        let section = installation_motherbee_section(
            &copy(Absent, None, None),
            &Ok(InstallationVersions::default()),
            Some("hive.yaml's ai is not one every reader can use (x)"),
            InstallationVersionsAsk::default(),
        );
        assert_eq!(section["state"], serde_json::json!("pending"));
        assert_eq!(
            section["not_written"],
            serde_json::json!("hive.yaml's ai is not one every reader can use (x)")
        );
        assert_eq!(section["version"], serde_json::Value::Null);
        let section = installation_motherbee_section(
            &motherbee,
            &Err("bad record".to_string()),
            None,
            InstallationVersionsAsk::default(),
        );
        assert_eq!(section["state"], serde_json::json!("unknown"));
        assert_eq!(section["records_error"], serde_json::json!("bad record"));
        assert!(section.get("not_written").is_none());
    }

    /// FINDINGS A-198: the motherbee's `/versions` lists the newest 20 versions of the
    /// installation file, with how many there are and where the older ones start, so its config
    /// section stays within half a frame however many it recorded, each version at its largest.
    #[test]
    fn the_installation_versions_come_newest_first_in_pages_within_half_a_frame() {
        // A version at its largest plausible: both providers with long model names.
        let model = "m".repeat(64);
        let ai: HiveAiConfig = serde_json::from_value(serde_json::json!({
            "default_provider": "anthropic",
            "providers": {
                "openai": { "model": model },
                "anthropic": { "model": model },
            },
        }))
        .expect("ai");
        let records = InstallationVersions {
            versions: (1..=500u64)
                .map(|version| InstallationVersionRecord {
                    version,
                    sha256: "a".repeat(64),
                    written_at_ms: 1_800_000_000_000,
                    source: INSTALLATION_SOURCE_OPERATOR.to_string(),
                    ai: Some(ai.clone()),
                })
                .collect(),
        };
        let own = InstallationCopy {
            file: InstallationCopyFile::Valid,
            version: Some(500),
            sha256: Some("a".repeat(64)),
            error: None,
            ai: Some(ai.clone()),
        };
        let listed = |section: &serde_json::Value| -> Vec<u64> {
            section["versions"]
                .as_array()
                .expect("versions")
                .iter()
                .filter_map(|record| record["version"].as_u64())
                .collect()
        };
        let section = installation_motherbee_section(
            &own,
            &Ok(records.clone()),
            None,
            InstallationVersionsAsk::default(),
        );
        assert_eq!(listed(&section), (481..=500).collect::<Vec<_>>());
        assert_eq!(section["versions_total"], serde_json::json!(500));
        assert_eq!(section["versions_next_before"], serde_json::json!(481));
        let bytes = mesh_reply::serialized_len(&section);
        assert!(bytes <= 64 * 1024, "the default section is {bytes} bytes");
        // Older ones on request, and the largest count asked still within half a frame.
        let ask = InstallationVersionsAsk::from_payload(&serde_json::json!({
            "versions_limit": INSTALLATION_VERSIONS_MAX_LIMIT,
            "versions_before": "481",
        }))
        .expect("ask");
        let older = installation_motherbee_section(&own, &Ok(records.clone()), None, ask);
        assert_eq!(listed(&older), (381..=480).collect::<Vec<_>>());
        assert_eq!(older["versions_next_before"], serde_json::json!(381));
        let bytes = mesh_reply::serialized_len(&older);
        assert!(bytes <= 64 * 1024, "the largest page is {bytes} bytes");
        let first = installation_motherbee_section(
            &own,
            &Ok(records),
            None,
            InstallationVersionsAsk {
                limit: 20,
                before: Some(11),
            },
        );
        assert_eq!(listed(&first), (1..=10).collect::<Vec<_>>());
        assert!(first.get("versions_next_before").is_none());
        for refused in [
            serde_json::json!({ "versions_limit": 0 }),
            serde_json::json!({ "versions_limit": 101 }),
            serde_json::json!({ "versions_before": "soon" }),
        ] {
            assert!(
                InstallationVersionsAsk::from_payload(&refused).is_err(),
                "{refused}"
            );
        }
    }

    /// FINDINGS A-198: an answer the frame refuses goes as REPLY_TOO_LARGE in its place, the
    /// outcome of what ran kept in it and in the meta, never left for SY.admin to wait out.
    #[tokio::test]
    async fn an_orchestrator_answer_past_the_frame_goes_as_reply_too_large() {
        let (client, mut harness) = fluxbee_sdk::RouterDispatcherTestHarness::new_with_uuid(
            "orchestrator-test-uuid",
            "SY.orchestrator@motherbee",
            build_orchestrator_rpc_profile().expect("profile"),
        );
        let sender = client.sender_snapshot();
        let request = test_admin_command("trace-a198", "set_node_config", serde_json::json!({}));
        let huge = serde_json::json!({
            "status": "ok",
            "node_name": "AI.sales@motherbee",
            "config": { "prompt": "p".repeat(200_000) },
        });
        send_admin_reply(&sender, &request, "set_node_config", huge)
            .await
            .expect("answered");
        let reply = harness
            .next_outgoing_within(Duration::from_secs(1))
            .await
            .expect("a reply");
        assert_eq!(reply.meta.action.as_deref(), Some("set_node_config"));
        assert_eq!(
            reply.payload["error_code"],
            serde_json::json!(mesh_reply::REPLY_TOO_LARGE)
        );
        assert_eq!(
            reply.payload["outcome"],
            serde_json::json!({ "status": "ok", "node_name": "AI.sales@motherbee" })
        );
        assert_eq!(
            reply.meta.action_result.map(|result| result.as_str()),
            Some("applied")
        );
        // A system answer the same way, under its own message name.
        let request = test_system_message("trace-a198-2", "LIST_NODES", serde_json::json!({}));
        let huge = serde_json::json!({
            "status": "ok",
            "nodes": [{ "blob": "x".repeat(200_000) }],
        });
        send_system_action_response(&sender, &request, "LIST_NODES_RESPONSE", huge)
            .await
            .expect("answered");
        let reply = harness
            .next_outgoing_within(Duration::from_secs(1))
            .await
            .expect("a reply");
        assert_eq!(reply.meta.msg.as_deref(), Some("LIST_NODES_RESPONSE"));
        assert_eq!(
            reply.payload["error_code"],
            serde_json::json!(mesh_reply::REPLY_TOO_LARGE)
        );
        let message = reply.payload["message"].as_str().expect("message");
        assert!(message.contains("limit and cursor"), "{message}");
    }

    /// FINDINGS A-198: `/versions`' pages go motherbee first, then the spokes by id, and a node
    /// listing's by hive, then name; a cursor whose row has gone keeps its place.
    #[test]
    fn the_versions_and_node_pages_keep_their_order() {
        assert!(versions_hive_after("worker1", "motherbee", "motherbee"));
        assert!(!versions_hive_after("motherbee", "motherbee", "motherbee"));
        assert!(versions_hive_after("worker2", "worker1", "motherbee"));
        assert!(!versions_hive_after("worker1", "worker1", "motherbee"));
        assert!(!versions_hive_after("motherbee", "worker1", "motherbee"));

        let node = |hive: &str, name: &str| serde_json::json!({ "hive": hive, "name": name });
        let nodes = vec![
            node("worker1", "SY.b@worker1"),
            node("motherbee", "SY.z@motherbee"),
            node("worker1", "AI.a@worker1"),
            node("motherbee", "AI.c@motherbee"),
        ];
        let names = |page: &mesh_reply::ListPage| -> Vec<String> {
            page.rows
                .iter()
                .filter_map(|row| row["name"].as_str().map(str::to_string))
                .collect()
        };
        let whole = node_rows_page(nodes.clone(), &PageAsk::default());
        assert_eq!(
            names(&whole),
            vec![
                "AI.c@motherbee",
                "SY.z@motherbee",
                "AI.a@worker1",
                "SY.b@worker1"
            ]
        );
        let first = node_rows_page(
            nodes.clone(),
            &PageAsk {
                limit: Some(3),
                cursor: None,
            },
        );
        assert_eq!(first.next_cursor.as_deref(), Some("worker1|AI.a@worker1"));
        let rest = node_rows_page(
            nodes,
            &PageAsk {
                limit: Some(3),
                cursor: first.next_cursor,
            },
        );
        assert_eq!(names(&rest), vec!["SY.b@worker1"]);
        assert_eq!(rest.next_cursor, None);
        assert_eq!(rest.total, 4);
    }

    /// The join copies the motherbee's installation file to the spoke's dist, at the same place
    /// and mode as the motherbee's, before the spoke's readers first start.
    #[test]
    fn the_join_copies_the_installation_file_where_the_spoke_reads_it() {
        let command = installation_sync_promote_command(
            "/tmp/fluxbee-installation-sync-worker9",
            Path::new("/var/lib/fluxbee/dist"),
        );
        assert!(command.starts_with("set -euo pipefail && "), "{command}");
        assert!(
            command.contains("mkdir -p '/var/lib/fluxbee/dist/installation'"),
            "{command}"
        );
        assert!(
            command.contains(
                "install -m 0644 '/tmp/fluxbee-installation-sync-worker9/installation.json' '/var/lib/fluxbee/dist/installation/installation.json'"
            ),
            "{command}"
        );
        assert!(command.ends_with("rm -rf '/tmp/fluxbee-installation-sync-worker9'"));
        // The worker's hive.yaml carries no ai: its readers read the file.
        let worker = render_worker_hive_yaml(
            "worker9",
            "10.0.0.1:9000",
            "/var/lib/fluxbee",
            "SY.frontdesk.gov@motherbee",
            "10.0.0.1:9100",
            &sample_blob_config(),
            &sample_dist_config(),
            "",
        );
        let value: serde_yaml::Value = serde_yaml::from_str(&worker).expect("yaml");
        assert!(value.get("ai").is_none(), "{worker}");
    }

    // --- The operator's change (docs/hive-config-update-v1.md §4, stage 3c) ---

    /// An `ai` with `default` as its default provider and these models.
    fn operator_ai(
        default: fluxbee_ai_sdk::AiProvider,
        openai: Option<&str>,
        anthropic: Option<&str>,
    ) -> HiveAiConfig {
        let model = |model: Option<&str>| {
            model.map(|model| fluxbee_ai_sdk::AiProviderModelConfig {
                model: model.to_string(),
            })
        };
        HiveAiConfig {
            default_provider: default,
            providers: fluxbee_ai_sdk::AiProviderConfigs {
                openai: model(openai),
                anthropic: model(anthropic),
            },
        }
    }

    /// 8.x's values: Claude by default, both providers listed.
    fn claude_by_default() -> HiveAiConfig {
        operator_ai(
            fluxbee_ai_sdk::AiProvider::Anthropic,
            Some("gpt-5.5"),
            Some("claude-sonnet-5-5"),
        )
    }

    fn write_request(ai: HiveAiConfig, expected_version: u64) -> InstallationWriteRequest {
        InstallationWriteRequest {
            ai,
            expected_version,
            replace_hand_edit: false,
        }
    }

    /// A motherbee holding version 1 as stage 3b wrote it, from 8.x's values, its record without
    /// them: (root, dist, file, records).
    fn motherbee_at_version_1(tag: &str) -> (PathBuf, PathBuf, PathBuf, PathBuf) {
        let root = installation_temp_root(tag);
        let dist = root.join("dist");
        let file = installation_file_path(&dist);
        let records = root.join("orchestrator").join("installation-versions.json");
        let yaml = serde_yaml::to_value(claude_by_default()).expect("yaml");
        write_installation_file_first_version(&file, &records, Some(&yaml), 1_000).expect("v1");
        let mut recorded = read_installation_versions(&records).expect("records");
        recorded.versions[0].ai = None;
        write_installation_versions(&records, &recorded).expect("as 3b recorded it");
        (root, dist, file, records)
    }

    /// The write: the next version, its values recorded with it before the file, mode 0644; version
    /// 1's values filled in from its file; and the answer names the version it replaced.
    #[test]
    fn the_motherbee_writes_the_operator_s_next_version_with_its_values() {
        let (root, dist, file, records) = motherbee_at_version_1("write");
        let v1_sha256 = sha256_hex(&fs::read(&file).expect("v1"));
        let openai_set = operator_ai(
            fluxbee_ai_sdk::AiProvider::Anthropic,
            Some("gpt-5.6"),
            Some("claude-sonnet-5-5"),
        );
        let written = write_installation_operator_version(
            true,
            false,
            &file,
            &records,
            &write_request(openai_set.clone(), 1),
            2_000,
        )
        .expect("written");
        let bytes = fs::read(&file).expect("v2");
        assert_eq!(
            written,
            InstallationWritten {
                version: 2,
                sha256: sha256_hex(&bytes),
                previous_version: 1,
                previous_sha256: Some(v1_sha256.clone()),
            }
        );
        let parsed = InstallationFile::parse(&bytes).expect("every reader reads it");
        assert_eq!(parsed.version, 2);
        assert_eq!(parsed.ai, Some(openai_set.clone()));
        assert_eq!(
            fs::metadata(&file).expect("meta").permissions().mode() & 0o777,
            0o644
        );
        let recorded = read_installation_versions(&records).expect("records");
        assert_eq!(
            recorded.versions,
            vec![
                InstallationVersionRecord {
                    version: 1,
                    sha256: v1_sha256,
                    written_at_ms: 1_000,
                    source: "migration".to_string(),
                    ai: Some(claude_by_default()),
                },
                InstallationVersionRecord {
                    version: 2,
                    sha256: written.sha256.clone(),
                    written_at_ms: 2_000,
                    source: "operator".to_string(),
                    ai: Some(openai_set.clone()),
                },
            ]
        );
        let own = InstallationCopy::read(&dist);
        assert_eq!(installation_motherbee_state(&own, Ok(&recorded)), "current");
        assert_eq!(own.ai, Some(openai_set));
        // /versions lists every version with its values.
        let section = installation_motherbee_section(
            &own,
            &Ok(recorded.clone()),
            None,
            InstallationVersionsAsk::default(),
        );
        assert_eq!(
            section["versions"][0]["ai"]["default_provider"],
            "anthropic"
        );
        assert_eq!(section["versions"][1]["source"], "operator");
        assert_eq!(
            section["versions"][1]["ai"]["providers"]["openai"]["model"],
            "gpt-5.6"
        );

        // Undo: version 1's values back, as version 3.
        let undone = write_installation_operator_version(
            true,
            false,
            &file,
            &records,
            &write_request(claude_by_default(), 2),
            3_000,
        )
        .expect("undone");
        assert_eq!((undone.version, undone.previous_version), (3, 2));
        assert_eq!(
            InstallationFile::parse(&fs::read(&file).expect("v3"))
                .expect("v3")
                .ai,
            Some(claude_by_default())
        );
        let _ = fs::remove_dir_all(&root);
    }

    /// Each refusal writes nothing, and says why with its code.
    #[test]
    fn the_write_refuses_and_writes_nothing() {
        let (root, _dist, file, records) = motherbee_at_version_1("refuse");
        let v1 = fs::read(&file).expect("v1");
        let recorded_v1 = fs::read(&records).expect("records");
        let change = operator_ai(fluxbee_ai_sdk::AiProvider::OpenAi, Some("gpt-5.6"), None);
        let refused = |is_motherbee: bool, busy: bool, request: &InstallationWriteRequest| {
            write_installation_operator_version(is_motherbee, busy, &file, &records, request, 9)
                .expect_err("refused")
        };
        let request = write_request(change.clone(), 1);
        assert_eq!(refused(false, false, &request).code, "NOT_PRIMARY");
        let busy = refused(true, true, &request);
        assert_eq!(busy.code, "JOIN_IN_PROGRESS");
        assert!(
            busy.message.contains("joining or being removed"),
            "{busy:?}"
        );
        let conflict = refused(true, false, &write_request(change.clone(), 2));
        assert_eq!(conflict.code, "VERSION_CONFLICT");
        assert!(
            conflict.message.contains("at version 1, not 2"),
            "{conflict:?}"
        );
        let unchanged = refused(true, false, &write_request(claude_by_default(), 1));
        assert_eq!(unchanged.code, "INSTALLATION_UNCHANGED");
        assert!(unchanged.message.contains("version 1"), "{unchanged:?}");
        assert_eq!(fs::read(&file).expect("v1"), v1);
        assert_eq!(fs::read(&records).expect("records"), recorded_v1);

        // Values no reader can use never reach the write.
        let invalid = parse_installation_write(&serde_json::json!({
            "ai": {"default_provider": "anthropic", "providers": {"openai": {"model": "gpt-5.5"}}},
            "expected_version": 1,
        }))
        .expect_err("no model for its default provider");
        assert_eq!(invalid.code, "INVALID_AI_SETTINGS");
        assert!(
            invalid.message.contains("ai.providers.anthropic"),
            "{invalid:?}"
        );

        // A hand edit: refused, unless the change replaces it, as the next version over it.
        let mut edited: serde_json::Value = serde_json::from_slice(&v1).expect("json");
        edited["ai"]["providers"]["anthropic"]["model"] = serde_json::json!("claude-opus-5-5");
        let edited = serde_json::to_vec_pretty(&edited).expect("bytes");
        fs::write(&file, &edited).expect("edited by hand");
        let hand = refused(true, false, &request);
        assert_eq!(hand.code, "INSTALLATION_EDITED_BY_HAND");
        assert!(hand.message.contains("replace_hand_edit"), "{hand:?}");
        assert_eq!(fs::read(&file).expect("as edited"), edited);
        let replaced = write_installation_operator_version(
            true,
            false,
            &file,
            &records,
            &InstallationWriteRequest {
                replace_hand_edit: true,
                ..request.clone()
            },
            10,
        )
        .expect("replaces the hand edit");
        assert_eq!(replaced.version, 2);
        assert_eq!(replaced.previous_sha256, Some(sha256_hex(&edited)));
        // Version 1's values stay unknown: the file was not version 1's any more.
        let recorded = read_installation_versions(&records).expect("records");
        assert_eq!(recorded.record_for(1).expect("v1").ai, None);

        // A file no reader can use: its version is the last one recorded, and a hand edit that
        // raised the version is passed by the next one.
        fs::write(&file, b"{\"schema_version\":1,\"version\":0}").expect("broken");
        let broken = refused(true, false, &write_request(change.clone(), 2));
        assert_eq!(broken.code, "INSTALLATION_EDITED_BY_HAND");
        assert!(
            broken.message.contains("not one any reader can use"),
            "{broken:?}"
        );
        let raised = InstallationFile {
            schema_version: INSTALLATION_SCHEMA_VERSION,
            version: 7,
            ai: Some(claude_by_default()),
        }
        .render()
        .expect("v7");
        fs::write(&file, &raised).expect("raised by hand");
        let over = write_installation_operator_version(
            true,
            false,
            &file,
            &records,
            &InstallationWriteRequest {
                ai: change.clone(),
                expected_version: 7,
                replace_hand_edit: true,
            },
            11,
        )
        .expect("over the raised version");
        assert_eq!((over.version, over.previous_version), (8, 7));

        // No file: version 1 is its start's to write; a later version, put back by hand.
        fs::remove_file(&file).expect("gone");
        let missing = refused(true, false, &write_request(change.clone(), 8));
        assert_eq!(missing.code, "INSTALLATION_NOT_WRITTEN");
        assert!(
            missing.message.contains("version 8 was recorded"),
            "{missing:?}"
        );
        let fresh = installation_temp_root("fresh");
        let fresh_file = installation_file_path(&fresh.join("dist"));
        let none = write_installation_operator_version(
            true,
            false,
            &fresh_file,
            &fresh.join("installation-versions.json"),
            &write_request(change.clone(), 0),
            12,
        )
        .expect_err("no file yet");
        assert_eq!(none.code, "INSTALLATION_NOT_WRITTEN");
        assert!(none.message.contains("restart sy-orchestrator"), "{none:?}");
        assert!(!fresh_file.exists());
        let _ = fs::remove_dir_all(&fresh);
        let _ = fs::remove_dir_all(&root);
    }

    /// The record is written before the file: a record that cannot be written leaves the file as
    /// it was.
    #[test]
    fn a_version_whose_record_cannot_be_written_is_not_written() {
        let (root, _dist, file, _records) = motherbee_at_version_1("record-first");
        let v1 = fs::read(&file).expect("v1");
        // A records directory that is a dangling link: it reads as no record, and cannot be written.
        let gone = root.join("gone");
        std::os::unix::fs::symlink(root.join("nowhere"), &gone).expect("link");
        let records = gone.join("installation-versions.json");
        let refused = write_installation_operator_version(
            true,
            false,
            &file,
            &records,
            &InstallationWriteRequest {
                ai: operator_ai(fluxbee_ai_sdk::AiProvider::OpenAi, Some("gpt-5.6"), None),
                expected_version: 1,
                // No record of version 1 there: the file reads as a hand edit.
                replace_hand_edit: true,
            },
            5,
        )
        .expect_err("no record, no file");
        assert_eq!(refused.code, "INSTALLATION_WRITE_FAILED");
        assert!(
            refused.message.contains("nothing was written"),
            "{refused:?}"
        );
        assert_eq!(fs::read(&file).expect("still v1"), v1);
        let _ = fs::remove_dir_all(&root);
    }

    /// The write form takes exactly `{ai, expected_version, replace_hand_edit?}`; the apply form is
    /// the usual one, and `write` belongs to category config alone.
    #[test]
    fn a_config_update_is_a_write_or_an_apply() {
        let write = serde_json::json!({
            "category": "config",
            "write": {
                "ai": {"default_provider": "openai", "providers": {"openai": {"model": "gpt-5.5"}}},
                "expected_version": 3,
                "replace_hand_edit": null,
            },
        });
        assert!(is_installation_write(&write));
        let parsed = parse_installation_write(&write["write"]).expect("the write");
        assert_eq!(parsed.expected_version, 3);
        assert!(!parsed.replace_hand_edit, "null is absent");
        for (fields, code, reason) in [
            (
                serde_json::json!("x"),
                "INVALID_REQUEST",
                "write must be an object",
            ),
            (
                serde_json::json!({"ai": parsed.ai, "expected_version": 3, "force": true}),
                "INVALID_REQUEST",
                "write.force is not a field of the write",
            ),
            (
                serde_json::json!({"ai": parsed.ai}),
                "INVALID_REQUEST",
                "write.expected_version is required",
            ),
            (
                serde_json::json!({"ai": parsed.ai, "expected_version": 3, "replace_hand_edit": "yes"}),
                "INVALID_REQUEST",
                "replace_hand_edit must be true or false",
            ),
            (
                serde_json::json!({"expected_version": 3}),
                "INVALID_AI_SETTINGS",
                "ai must be an object",
            ),
        ] {
            let refused = parse_installation_write(&fields).expect_err(reason);
            assert_eq!(refused.code, code, "{refused:?}");
            assert!(refused.message.contains(reason), "{refused:?}");
        }

        let apply = serde_json::json!({
            "category": "config",
            "manifest_version": 3,
            "manifest_hash": "abc",
        });
        assert!(!is_installation_write(&apply));
        let parsed = parse_system_update_payload(&apply).expect("the apply");
        assert_eq!(
            (parsed.category.as_str(), parsed.manifest_version),
            ("config", 3)
        );
        let misplaced = parse_system_update_payload(&serde_json::json!({
            "category": "core",
            "manifest_hash": "abc",
            "write": {},
        }))
        .expect_err("write belongs to config");
        assert!(misplaced.to_string().contains("only for category=config"));
        assert!(parse_system_update_payload(&serde_json::json!({
            "category": "config",
            "manifest_hash": "abc",
            "runtime": "ai.generic",
        }))
        .is_err());
    }

    /// A hive answers `sync_pending` until its copy is the version and the hash an update names;
    /// a copy past the version named refuses it.
    #[test]
    fn a_config_update_waits_until_the_hive_holds_its_version_and_hash() {
        let root = installation_temp_root("sync");
        let dist = root.join("dist");
        let file = installation_file_path(&dist);
        fs::create_dir_all(file.parent().expect("its dir")).expect("dist/installation");
        let render = |version: u64, ai: HiveAiConfig| {
            InstallationFile {
                schema_version: INSTALLATION_SCHEMA_VERSION,
                version,
                ai: Some(ai),
            }
            .render()
            .expect("renders")
        };
        let v2 = render(2, claude_by_default());
        let v2_sha256 = sha256_hex(&v2);
        let check = |version: u64, sha256: &str| {
            manifest_match(
                version,
                sha256,
                &local_system_manifest_state("config", &dist).expect("state"),
            )
        };
        assert_eq!(check(2, &v2_sha256), ManifestMatch::Mismatch, "absent");
        fs::write(&file, render(1, claude_by_default())).expect("v1");
        assert_eq!(check(2, &v2_sha256), ManifestMatch::Behind);
        let other = render(
            2,
            operator_ai(fluxbee_ai_sdk::AiProvider::OpenAi, Some("gpt-5.5"), None),
        );
        fs::write(&file, &other).expect("another v2");
        assert_eq!(check(2, &v2_sha256), ManifestMatch::Mismatch);
        // Stage 3c's review (F5): for category config, version 2 with another hash is refused,
        // never sync_pending; another category, or another version, stays as it was.
        let local = local_system_manifest_state("config", &dist).expect("state");
        assert!(config_hash_differs_within_version("config", 2, &local));
        assert!(!config_hash_differs_within_version("core", 2, &local));
        assert!(!config_hash_differs_within_version("config", 0, &local));
        assert!(!config_hash_differs_within_version("config", 3, &local));
        fs::write(&file, &v2).expect("v2");
        assert_eq!(check(2, &v2_sha256), ManifestMatch::Matched);
        assert_eq!(
            check(2, &format!("sha256:{v2_sha256}")),
            ManifestMatch::Matched
        );
        assert_eq!(check(0, &v2_sha256), ManifestMatch::Matched, "no version");
        fs::write(&file, render(3, claude_by_default())).expect("v3");
        assert_eq!(check(2, &v2_sha256), ManifestMatch::Ahead);
        fs::write(&file, b"{\"schema_version\":1,\"version\":0}").expect("broken");
        assert_eq!(check(2, &v2_sha256), ManifestMatch::Mismatch);
        let _ = fs::remove_dir_all(&root);
    }

    /// The readers a config update restarts, by role: those that take `ai` at their start and that
    /// the role runs.
    #[test]
    fn each_role_restarts_only_its_start_readers() {
        assert_eq!(
            installation_start_reader_services(HiveRole::Motherbee),
            vec!["sy-cognition", "sy-frontdesk-gov"]
        );
        assert_eq!(
            installation_start_reader_services(HiveRole::Worker),
            vec!["sy-cognition"]
        );
        assert!(installation_start_reader_services(HiveRole::Ingress).is_empty());
        assert!(installation_start_reader_services(HiveRole::Egress).is_empty());
        for role in HiveRole::ALL {
            let runs = system_nodes_for_role(role).nodes;
            for reader in installation_start_readers(role) {
                assert!(
                    runs.iter().any(|node| node == reader),
                    "{reader} is not a node of {}",
                    role.as_str()
                );
            }
            // SY.admin and Archi take a new version at their next use: a restart could cut the
            // very action that wrote it.
            for never in ["SY.admin", "SY.architect", "SY.orchestrator"] {
                assert!(!installation_start_readers(role).contains(&never));
            }
        }
    }

    /// The restart decision: without a record every reader restarts; a change of the engine (the
    /// default provider or its model) restarts them; another provider's model, or the same
    /// version again, restarts nothing. A reader active since another time than the record's runs
    /// an engine nothing says, and restarts (stage 3c's review, F2).
    #[test]
    fn a_config_update_restarts_the_readers_only_when_their_engine_changes() {
        let services = installation_start_reader_services(HiveRole::Motherbee);
        // Both readers active since the times the last update recorded.
        let readers: Vec<ReaderNow> = services
            .iter()
            .enumerate()
            .map(|(at, service)| ReaderNow {
                service: service.clone(),
                active_since: Some(1_000 + at as u64),
            })
            .collect();
        let applied = |version: u64, sha256: &str, ai: HiveAiConfig| ConfigAppliedRecord {
            version,
            sha256: sha256.to_string(),
            applied_at_ms: 1,
            ai,
            restarted: Vec::new(),
            active_since: readers
                .iter()
                .map(|reader| (reader.service.clone(), reader.active_since.expect("active")))
                .collect(),
        };
        let restart_all = ConfigUpdatePlan::Apply {
            restart: services.clone(),
            unchanged: Vec::new(),
        };
        let restart_none = ConfigUpdatePlan::Apply {
            restart: Vec::new(),
            unchanged: services.clone(),
        };
        // A hive's first config update: nothing says what its readers run.
        assert_eq!(
            config_update_plan(&readers, None, 2, "bbb", &claude_by_default()),
            restart_all
        );
        let v1 = applied(1, "aaa", claude_by_default());
        // The gate's change: OpenAI's model, not the default provider's.
        let openai_model = operator_ai(
            fluxbee_ai_sdk::AiProvider::Anthropic,
            Some("gpt-5.6"),
            Some("claude-sonnet-5-5"),
        );
        assert_eq!(
            config_update_plan(&readers, Some(&v1), 2, "bbb", &openai_model),
            restart_none
        );
        // The default provider's model.
        let claude_model = operator_ai(
            fluxbee_ai_sdk::AiProvider::Anthropic,
            Some("gpt-5.5"),
            Some("claude-opus-5-5"),
        );
        assert_eq!(
            config_update_plan(&readers, Some(&v1), 2, "bbb", &claude_model),
            restart_all
        );
        // The default provider.
        let openai_default = operator_ai(
            fluxbee_ai_sdk::AiProvider::OpenAi,
            Some("gpt-5.5"),
            Some("claude-sonnet-5-5"),
        );
        assert_eq!(
            config_update_plan(&readers, Some(&v1), 2, "bbb", &openai_default),
            restart_all
        );
        // The same version and hash again: applied already.
        assert_eq!(
            config_update_plan(&readers, Some(&v1), 1, "sha256:aaa", &claude_by_default()),
            ConfigUpdatePlan::AlreadyApplied
        );
        // An ingress runs no reader: nothing to restart, whatever changed.
        assert_eq!(
            config_update_plan(&[], None, 2, "bbb", &openai_default),
            ConfigUpdatePlan::Apply {
                restart: Vec::new(),
                unchanged: Vec::new(),
            }
        );

        // F2's case: v2 (opus) restarted both readers, and its record could not be written, so the
        // hive still records v1 (sonnet). The operator undoes with v3, v1's values: sonnet against
        // sonnet, and still both restart, since each became active after the record.
        let since_v2: Vec<ReaderNow> = readers
            .iter()
            .map(|reader| ReaderNow {
                active_since: reader.active_since.map(|since| since + 50_000),
                ..reader.clone()
            })
            .collect();
        assert_eq!(
            config_update_plan(&since_v2, Some(&v1), 3, "ccc", &claude_by_default()),
            restart_all
        );
        // One reader restarted for another reason since; the other still runs what was recorded.
        let mut one_restarted = readers.clone();
        one_restarted[1].active_since = Some(99_999);
        assert_eq!(
            config_update_plan(&one_restarted, Some(&v1), 2, "bbb", &openai_model),
            ConfigUpdatePlan::Apply {
                restart: vec![services[1].clone()],
                unchanged: vec![services[0].clone()],
            }
        );
        // A reader whose activation cannot be read, or one the record does not name (a box joined
        // again, a record of before this fix): unknown, restarted.
        let mut unreadable = readers.clone();
        unreadable[0].active_since = None;
        let mut unnamed = v1.clone();
        unnamed.active_since.clear();
        for (now, record) in [(&unreadable, &v1), (&readers, &unnamed)] {
            let ConfigUpdatePlan::Apply { restart, .. } =
                config_update_plan(now, Some(record), 2, "bbb", &openai_model)
            else {
                panic!("a plan");
            };
            assert!(restart.contains(&services[0]), "{restart:?}");
        }
        // The same version and hash restarts nothing, however the readers came up since.
        assert_eq!(
            config_update_plan(&since_v2, Some(&v1), 1, "aaa", &claude_by_default()),
            ConfigUpdatePlan::AlreadyApplied
        );
        assert_eq!(parse_active_since(" 123456789\n"), Some(123_456_789));
        assert_eq!(parse_active_since("0"), None);
        assert_eq!(parse_active_since(""), None);
        // A box removed from the installation forgets what it applied.
        assert!(remove_hive_cleanup_script()
            .contains(&format!("rm -f {}", config_applied_path().display())));
        // A reader that did not restart, and a record that could not be written, by their codes.
        let unwritten = format!("{CONFIG_RECORD_UNWRITTEN} (disk full)");
        assert_eq!(
            config_update_error_code(std::slice::from_ref(&unwritten)),
            "CONFIG_RECORD_FAILED"
        );
        assert_eq!(
            config_update_error_code(&["sy-cognition: bootstrap timeout".to_string(), unwritten]),
            "RESTART_FAILED"
        );
    }

    /// What a hive applied last: its record, and `/versions`' `config.applied`.
    #[test]
    fn a_hive_records_the_config_update_it_applied() {
        let root = installation_temp_root("applied");
        let path = root.join("orchestrator").join("config-applied.json");
        assert_eq!(read_config_applied(&path), Ok(None));
        assert_eq!(
            config_applied_json(&read_config_applied(&path)),
            serde_json::Value::Null
        );
        let record = ConfigAppliedRecord {
            version: 2,
            sha256: "bbb".to_string(),
            applied_at_ms: 42,
            ai: claude_by_default(),
            restarted: vec!["sy-cognition".to_string()],
            active_since: BTreeMap::from([("sy-cognition".to_string(), 7_000_000)]),
        };
        write_config_applied(&path, &record).expect("written");
        assert_eq!(
            fs::metadata(&path).expect("meta").permissions().mode() & 0o777,
            0o644
        );
        assert_eq!(read_config_applied(&path), Ok(Some(record.clone())));
        let shown = config_applied_json(&read_config_applied(&path));
        assert_eq!(shown["version"], 2);
        assert_eq!(shown["restarted"], serde_json::json!(["sy-cognition"]));
        assert_eq!(shown["ai"]["default_provider"], "anthropic");
        fs::write(&path, b"not json").expect("broken");
        assert!(config_applied_json(&read_config_applied(&path))["error"]
            .as_str()
            .is_some_and(|err| err.contains("does not decode")));
        let _ = fs::remove_dir_all(&root);
    }

    /// The motherbee's start fills in the values of the version its file holds, once, and never
    /// those of a file edited by hand.
    #[test]
    fn the_start_records_the_current_version_s_values_once() {
        let (root, _dist, file, records) = motherbee_at_version_1("fill");
        record_current_version_values_at_start(&file, &records);
        let recorded = read_installation_versions(&records).expect("records");
        assert_eq!(
            recorded.record_for(1).expect("v1").ai,
            Some(claude_by_default())
        );
        let mut without = recorded.clone();
        without.versions[0].ai = None;
        write_installation_versions(&records, &without).expect("as 3b");
        fs::write(&file, b"{\"schema_version\":1,\"version\":1}").expect("edited");
        record_current_version_values_at_start(&file, &records);
        assert_eq!(
            read_installation_versions(&records)
                .expect("records")
                .record_for(1)
                .expect("v1")
                .ai,
            None
        );
        let _ = fs::remove_dir_all(&root);
    }

    fn sample_core_manifest() -> CoreManifest {
        let mut components = std::collections::BTreeMap::new();
        for (name, sha, size) in [
            ("rt-gateway", "aa11", 10u64),
            ("sy-config-routes", "bb22", 20),
            ("sy-orchestrator", "cc33", 30),
            ("sy-edge", "dd44", 40),
            ("sy-architect", "ee55", 181_123_776),
        ] {
            components.insert(
                name.to_string(),
                CoreManifestComponent {
                    service: name.to_string(),
                    version: "0.1.0".to_string(),
                    build_id: "build-1".to_string(),
                    sha256: sha.to_string(),
                    size: Some(size),
                },
            );
        }
        CoreManifest {
            schema_version: 1,
            components,
        }
    }

    /// Scoping copies entries verbatim — same sha256, size, version, build_id.
    ///
    /// This runs on motherbee as a PRE-FLIGHT: it proves every component a role claims exists
    /// in the build before any file is copied. (The manifest that actually ships is the whole
    /// one — see `materialize_role_core_trees` — because the staleness gate compares its sha
    /// between motherbee and the spoke.)
    #[test]
    fn scoped_core_manifest_copies_entries_verbatim() {
        let full = sample_core_manifest();
        let wanted = vec!["rt-gateway".to_string(), "sy-edge".to_string()];
        let scoped = scope_core_manifest_to_components(&full, &wanted).unwrap();

        assert_eq!(scoped.schema_version, full.schema_version);
        assert_eq!(scoped.components.len(), 2);
        for name in &wanted {
            let a = full.components.get(name).unwrap();
            let b = scoped.components.get(name).unwrap();
            assert_eq!(a.sha256, b.sha256);
            assert_eq!(a.size, b.size);
            assert_eq!(a.version, b.version);
            assert_eq!(a.build_id, b.build_id);
        }
        // The 181 MB motherbee-only component is exactly what an ingress must not receive.
        assert!(!scoped.components.contains_key("sy-architect"));
    }

    /// A role asking for a component the build does not contain must fail loudly at
    /// materialization time, on motherbee — not silently ship an incomplete tree that every
    /// spoke of the role reports and whose core update it refuses.
    #[test]
    fn scoping_a_missing_component_fails_loudly() {
        let full = sample_core_manifest();
        let err = scope_core_manifest_to_components(&full, &["sy-nonexistent".to_string()])
            .expect_err("must reject a component absent from the manifest");
        assert!(err.to_string().contains("sy-nonexistent"));
    }

    /// A core manifest that describes each of `entries` by its bytes.
    fn core_manifest_of(entries: &[(&str, &[u8])]) -> CoreManifest {
        let mut components = std::collections::BTreeMap::new();
        for (name, bytes) in entries {
            components.insert(
                name.to_string(),
                CoreManifestComponent {
                    service: name.to_string(),
                    version: "0.1.114".to_string(),
                    build_id: "build-a186".to_string(),
                    sha256: format!("{:x}", Sha256::digest(bytes)),
                    size: Some(bytes.len() as u64),
                },
            );
        }
        CoreManifest {
            schema_version: 1,
            components,
        }
    }

    fn a186_temp_root(tag: &str) -> PathBuf {
        let root = std::env::temp_dir().join(format!("fb-a186-{tag}-{}", Uuid::new_v4().simple()));
        fs::create_dir_all(&root).expect("temp root");
        root
    }

    /// FINDINGS A-186: the start's dist check returns a report, never an error. A binary still
    /// to arrive, one of another build (same size, other bytes, or another size) and one the role
    /// lists that the manifest no longer names are each reported, with why, in the role's order;
    /// the binary that matches is not.
    #[test]
    fn the_start_dist_check_reports_a_missing_binary_and_a_hash_mismatch_instead_of_failing() {
        let root = a186_temp_root("check");
        let manifest = core_manifest_of(&[
            ("rt-gateway", b"router-new"),
            ("sy-cognition", b"cognition-new"),
            ("sy-timer", b"timer-new"),
            ("sy-identity", b"identity-new"),
        ]);
        fs::write(root.join("rt-gateway"), b"router-new").expect("rt-gateway");
        // Same size as the manifest's, other bytes: only its hash tells.
        fs::write(root.join("sy-timer"), b"timer-old").expect("sy-timer");
        fs::write(root.join("sy-identity"), b"identity-older").expect("sy-identity");
        fs::write(root.join("sy-gone"), b"gone").expect("sy-gone");
        let components: Vec<String> = [
            "rt-gateway",
            "sy-cognition",
            "sy-timer",
            "sy-identity",
            "sy-gone",
        ]
        .iter()
        .map(|name| name.to_string())
        .collect();

        let report = core_dist_mismatches(&manifest, &components, &root);
        let found: Vec<(&str, DistMismatchReason)> = report
            .iter()
            .map(|mismatch| (mismatch.component.as_str(), mismatch.reason))
            .collect();
        assert_eq!(
            found,
            vec![
                ("sy-cognition", DistMismatchReason::Missing),
                ("sy-timer", DistMismatchReason::HashMismatch),
                ("sy-identity", DistMismatchReason::SizeMismatch),
                ("sy-gone", DistMismatchReason::NotInManifest),
            ]
        );
        assert!(report[0].detail.contains("missing"), "{}", report[0].detail);
        assert!(
            report[1].detail.contains("hash mismatch") && report[1].detail.contains("expected="),
            "{}",
            report[1].detail
        );

        // Dist matching its manifest is an empty report.
        assert!(core_dist_mismatches(&manifest, &components[..1], &root).is_empty());
        let _ = fs::remove_dir_all(&root);
    }

    /// FINDINGS A-186, the update's side: the core update's check reads the same verdicts as the
    /// start's report and stays strict. Each binary the report lists is an error to it, so an
    /// update never installs one; a binary that matches passes.
    #[test]
    fn the_update_check_refuses_each_binary_the_start_only_reports() {
        let root = a186_temp_root("strict");
        let manifest = core_manifest_of(&[
            ("rt-gateway", b"router-new"),
            ("sy-cognition", b"cognition-new"),
            ("sy-timer", b"timer-new"),
        ]);
        fs::write(root.join("rt-gateway"), b"router-new").expect("rt-gateway");
        fs::write(root.join("sy-timer"), b"timer-old").expect("sy-timer");
        let path = |name: &str| root.join(name).display().to_string();

        validate_core_bins_against_manifest(&manifest, &[path("rt-gateway")])
            .expect("a binary that matches passes");
        for (name, says) in [("sy-cognition", "missing"), ("sy-timer", "hash mismatch")] {
            let err =
                validate_core_bins_against_manifest(&manifest, &[path("rt-gateway"), path(name)])
                    .expect_err("the update refuses what the start reports");
            assert!(err.to_string().contains(name), "{err}");
            assert!(err.to_string().contains(says), "{err}");
        }
        let _ = fs::remove_dir_all(&root);
    }

    /// FINDINGS A-186 (the DTAP panel's A-8): a role that lists a node its manifest no longer
    /// names is listed whole for the start, which runs what /usr/bin holds and reports it; the
    /// list a core update or a role tree reads still refuses it.
    #[test]
    fn a_role_listing_a_node_its_manifest_dropped_is_reported_not_refused_at_start() {
        let section = RoleSystemNodes {
            nodes: vec!["SY.config.routes".to_string(), "SY.gone".to_string()],
            wait_for: Vec::new(),
        };
        assert_eq!(
            core_component_names_in_section(&section),
            vec![
                "rt-gateway",
                "sy-config-routes",
                "sy-gone",
                "sy-orchestrator"
            ]
        );
        let err = core_component_names_from_section(&section, &sample_core_manifest())
            .expect_err("the update's list refuses it");
        assert!(err.to_string().contains("sy-gone"), "{err}");
    }

    /// FINDINGS A-186: a check that finds a mismatch opens `core.awaiting_update` in /versions, a
    /// later one keeps its start and takes its own components, and one that finds none, or a core
    /// update, closes it. A report a core update closed is not opened again by a check that ran
    /// before it.
    #[test]
    fn awaiting_update_opens_on_a_mismatch_and_closes_once_dist_matches() {
        let mismatch = |component: &str, reason: DistMismatchReason| DistMismatch {
            component: component.to_string(),
            reason,
            detail: format!("{component}: {}", reason.as_str()),
        };
        let open = awaiting_update_after(
            None,
            vec![mismatch("sy-timer", DistMismatchReason::Missing)],
            100,
        )
        .expect("a mismatch opens it");
        assert_eq!((open.since_ms, open.checked_at_ms), (100, 100));
        let later = awaiting_update_after(
            Some(&open),
            vec![mismatch("sy-timer", DistMismatchReason::SizeMismatch)],
            160,
        )
        .expect("still open");
        assert_eq!((later.since_ms, later.checked_at_ms), (100, 160));
        assert_eq!(later.mismatches[0].reason, DistMismatchReason::SizeMismatch);
        assert!(awaiting_update_after(Some(&later), Vec::new(), 220).is_none());
        // The journal names each reason as /versions does.
        for reason in [
            DistMismatchReason::NotInManifest,
            DistMismatchReason::InvalidEntry,
            DistMismatchReason::Missing,
            DistMismatchReason::Unreadable,
            DistMismatchReason::SizeMismatch,
            DistMismatchReason::HashMismatch,
        ] {
            assert_eq!(serde_json::json!(reason), reason.as_str());
        }

        let core = DistTree::Core;
        let state = sample_orchestrator_state_for_tests();
        assert!(
            local_versions_snapshot(&state, InstallationVersionsAsk::default())["core"]
                ["awaiting_update"]
                .is_null()
        );
        *awaiting_update_slot(&state, core) = Some(later);
        let shown = local_versions_snapshot(&state, InstallationVersionsAsk::default())["core"]
            ["awaiting_update"]
            .clone();
        assert_eq!(shown["reason"], "dist_mismatch");
        assert_eq!(shown["since_ms"], 100);
        assert_eq!(shown["components"][0]["component"], "sy-timer");
        assert_eq!(shown["components"][0]["reason"], "size_mismatch");
        assert!(shown["message"]
            .as_str()
            .is_some_and(|m| m.contains("/usr/bin")));

        assert!(refresh_awaiting_update(
            &state,
            core,
            vec![mismatch("sy-timer", DistMismatchReason::HashMismatch)]
        ));
        assert!(!refresh_awaiting_update(&state, core, Vec::new()));
        assert!(
            local_versions_snapshot(&state, InstallationVersionsAsk::default())["core"]
                ["awaiting_update"]
                .is_null()
        );

        // A core update's strict check closes it (`prepare_core_update`), and a recheck that ran
        // before the update does not open it again.
        *awaiting_update_slot(&state, core) = Some(open);
        assert!(!record_dist_check(&state, core, Vec::new()));
        assert!(!awaiting_update_open(&state, core));
        assert!(!refresh_awaiting_update(
            &state,
            core,
            vec![mismatch("sy-timer", DistMismatchReason::Missing)]
        ));
        assert!(!awaiting_update_open(&state, core));
    }

    /// FINDINGS A-186: the start checks dist only once Syncthing, which brings what dist lacks,
    /// has started, and runs no strict check of its own: a mismatch is the core update's to
    /// refuse. `main` starts the rechecks of an open report before it joins its router.
    #[test]
    fn the_start_checks_dist_after_syncthing_starts_and_never_stops_on_it() {
        let src = include_str!("sy_orchestrator.rs");
        let boot = &src[src.find("async fn bootstrap_local(").expect("boot")..];
        let boot = &boot[..boot.find("\n}\n").expect("its end")];
        let check = boot
            .find("check_core_dist_at_start(state, &core_manifest, &role_components);")
            .expect("the start's dist check");
        for syncthing in [
            "ensure_blob_sync_runtime(",
            "disable_blob_sync_runtime_local()",
        ] {
            let started = boot.rfind(syncthing).expect(syncthing);
            assert!(started < check, "{syncthing} comes before the dist check");
        }
        for strict in [
            "validate_core_manifest_for_bins(",
            "validate_core_bins_against_manifest(",
            "core_component_names_for_role(",
        ] {
            assert!(!boot.contains(strict), "the start runs no {strict}");
        }

        let main = &src[src
            .find("async fn main() -> Result<(), OrchestratorError> {")
            .expect("main")..];
        let after_start = &main[main
            .find("bootstrap_local(&state, &socket_dir).await?;")
            .expect("the start")..];
        let before_router = &after_start[..after_start
            .find("RouterDispatcher::connect_with_retry(")
            .expect("the router")];
        assert!(before_router.contains("run_dist_recheck_loop("));
    }

    /// FINDINGS A-186 on the motherbee: its start no longer stops on a dist that does not match,
    /// so each role tree checks what it copies. A tree whose sources do not all match takes none
    /// of them and keeps its manifest; once they match it takes them and the whole manifest,
    /// prunes what the role no longer runs, and a second pass changes nothing.
    #[test]
    fn a_role_tree_takes_no_binary_its_manifest_does_not_describe() {
        let root = a186_temp_root("tree");
        let source = root.join("src");
        let tree = root.join("worker");
        fs::create_dir_all(&source).expect("source");
        let manifest = core_manifest_of(&[
            ("rt-gateway", b"router-new"),
            ("sy-orchestrator", b"orchestrator-new"),
        ]);
        let manifest_path = root.join("manifest.json");
        fs::write(&manifest_path, "{\"schema_version\":1}\n").expect("manifest");
        fs::write(source.join("rt-gateway"), b"router-new").expect("rt-gateway");
        fs::write(source.join("sy-orchestrator"), b"orchestrator-bad").expect("bad");
        let components = vec!["rt-gateway".to_string(), "sy-orchestrator".to_string()];

        let err = materialize_core_tree(&manifest, &components, &source, &manifest_path, &tree)
            .expect_err("a source the manifest does not describe is refused");
        assert!(err.to_string().contains("sy-orchestrator"), "{err}");
        assert!(
            !tree.join("bin").join("rt-gateway").exists(),
            "nothing copied"
        );
        assert!(
            !tree.join("manifest.json").exists(),
            "the manifest untouched"
        );

        fs::write(source.join("sy-orchestrator"), b"orchestrator-new").expect("good");
        fs::write(tree.join("bin").join("sy-dropped"), b"old").expect("dropped");
        assert!(
            materialize_core_tree(&manifest, &components, &source, &manifest_path, &tree)
                .expect("matching sources")
        );
        assert_eq!(
            fs::read(tree.join("bin").join("sy-orchestrator")).expect("copied"),
            b"orchestrator-new"
        );
        assert!(!tree.join("bin").join("sy-dropped").exists(), "pruned");
        assert_eq!(
            fs::read_to_string(tree.join("manifest.json")).expect("manifest copied"),
            "{\"schema_version\":1}\n"
        );
        assert!(
            !materialize_core_tree(&manifest, &components, &source, &manifest_path, &tree)
                .expect("again")
        );
        let _ = fs::remove_dir_all(&root);
    }

    /// A vendor tree under `root`: `vendor/manifest.json` names `syncthing/syncthing` with the
    /// sha256 and size of `described`; that file holds `held`, and the installed binary,
    /// `bin/syncthing`, holds `installed` (none: no file).
    fn a189_vendor(
        root: &Path,
        described: &[u8],
        held: Option<&[u8]>,
        installed: Option<&[u8]>,
    ) -> SyncthingVendorPaths {
        let paths = SyncthingVendorPaths {
            vendor_root: root.join("vendor"),
            manifest: root.join("vendor").join("manifest.json"),
            installed: root.join("bin").join("syncthing"),
        };
        let manifest = serde_json::json!({
            "schema_version": 1,
            "version": 7,
            "components": {
                "syncthing": {
                    "upstream_version": "1.30.0",
                    "sha256": format!("sha256:{:x}", Sha256::digest(described)),
                    "size": described.len(),
                    "path": "syncthing/syncthing",
                }
            }
        });
        fs::create_dir_all(paths.vendor_root.join("syncthing")).expect("vendor tree");
        fs::create_dir_all(root.join("bin")).expect("bin");
        fs::write(&paths.manifest, manifest.to_string()).expect("vendor manifest");
        for (path, bytes) in [
            (paths.vendor_root.join("syncthing").join("syncthing"), held),
            (paths.installed.clone(), installed),
        ] {
            let _ = fs::remove_file(&path);
            if let Some(bytes) = bytes {
                fs::write(&path, bytes).expect("binary");
            }
        }
        paths
    }

    /// FINDINGS A-189: a vendored Syncthing that matches its manifest is installed when none is
    /// installed or another one is, and left alone when it is the one installed, whichever policy
    /// asks.
    #[test]
    fn the_vendored_syncthing_is_installed_once_it_matches_its_manifest() {
        let root = a186_temp_root("vendor-ok");
        let source = root.join("vendor").join("syncthing").join("syncthing");
        for policy in [VendorPolicy::Strict, VendorPolicy::KeepInstalled] {
            for installed in [None, Some(&b"syncthing-1"[..])] {
                let paths = a189_vendor(&root, b"syncthing-2", Some(b"syncthing-2"), installed);
                assert_eq!(
                    plan_syncthing_binary(&paths, policy),
                    Ok(SyncthingBinaryPlan::Install(source.clone())),
                    "{policy:?} with {installed:?} installed"
                );
            }
            let paths = a189_vendor(
                &root,
                b"syncthing-2",
                Some(b"syncthing-2"),
                Some(b"syncthing-2"),
            );
            assert_eq!(
                plan_syncthing_binary(&paths, policy),
                Ok(SyncthingBinaryPlan::Current)
            );
            let vendored = vendored_syncthing_at(&paths).expect("it matches");
            assert_eq!(
                vendored.sha256,
                format!("{:x}", Sha256::digest(b"syncthing-2"))
            );
        }
        let _ = fs::remove_dir_all(&root);
    }

    /// FINDINGS A-189: while dist/vendor does not hold the Syncthing its manifest describes
    /// (another build of the same size, a size of its own, the binary or the manifest not there
    /// yet, a manifest naming no Syncthing), the start, the watchdog and the sync probes keep the
    /// installed Syncthing and say why, and the vendor update refuses. Neither installs it.
    #[test]
    fn a_vendor_still_syncing_keeps_the_installed_syncthing_and_the_update_refuses_it() {
        let root = a186_temp_root("vendor-sync");
        let installed = Some(&b"syncthing-1"[..]);
        let check = |paths: &SyncthingVendorPaths, reason: DistMismatchReason| {
            match plan_syncthing_binary(paths, VendorPolicy::KeepInstalled) {
                Ok(SyncthingBinaryPlan::KeepInstalled(mismatch)) => {
                    assert_eq!(mismatch.component, "syncthing");
                    assert_eq!(mismatch.reason, reason, "{}", mismatch.detail);
                }
                other => panic!("the installed Syncthing is kept, not {other:?}"),
            }
            let refused = plan_syncthing_binary(paths, VendorPolicy::Strict)
                .expect_err("the vendor update refuses it");
            assert_eq!(refused.reason, reason, "{}", refused.detail);
        };
        check(
            &a189_vendor(&root, b"syncthing-2", Some(b"syncthing-3"), installed),
            DistMismatchReason::HashMismatch,
        );
        check(
            &a189_vendor(&root, b"syncthing-2.0", Some(b"syncthing-1"), installed),
            DistMismatchReason::SizeMismatch,
        );
        check(
            &a189_vendor(&root, b"syncthing-2", None, installed),
            DistMismatchReason::Missing,
        );
        let paths = a189_vendor(&root, b"syncthing-2", Some(b"syncthing-2"), installed);
        fs::write(&paths.manifest, r#"{"schema_version":1,"components":{}}"#).expect("manifest");
        check(&paths, DistMismatchReason::NotInManifest);
        fs::remove_file(&paths.manifest).expect("no manifest");
        check(&paths, DistMismatchReason::Missing);
        let _ = fs::remove_dir_all(&root);
    }

    /// FINDINGS A-189: with no Syncthing installed there is nothing to keep, so a vendor that does
    /// not match is an error whichever policy asks, as it was; the start and the watchdog log it
    /// and go on.
    #[test]
    fn with_no_syncthing_installed_a_vendor_that_does_not_match_stays_an_error() {
        let root = a186_temp_root("vendor-none");
        for policy in [VendorPolicy::Strict, VendorPolicy::KeepInstalled] {
            let paths = a189_vendor(&root, b"syncthing-2", Some(b"syncthing-3"), None);
            let err = plan_syncthing_binary(&paths, policy).expect_err("nothing to keep");
            assert_eq!(err.reason, DistMismatchReason::HashMismatch, "{policy:?}");
        }
        let _ = fs::remove_dir_all(&root);
    }

    /// FINDINGS A-189: `vendor.awaiting_update` reports the vendored Syncthing in the vendor
    /// section of /versions as `core.awaiting_update` reports the core, and closes on a check that
    /// finds it matching; the core's report is another one.
    #[test]
    fn vendor_awaiting_update_reports_the_vendor_as_core_awaiting_update_reports_the_core() {
        let state = sample_orchestrator_state_for_tests();
        let mismatch = DistMismatch {
            component: "syncthing".to_string(),
            reason: DistMismatchReason::HashMismatch,
            detail: "vendor manifest hash mismatch for 'syncthing'".to_string(),
        };
        assert!(record_dist_check(&state, DistTree::Vendor, vec![mismatch]));
        let snapshot = local_versions_snapshot(&state, InstallationVersionsAsk::default());
        let shown = &snapshot["vendor"]["awaiting_update"];
        assert_eq!(shown["reason"], "dist_mismatch");
        assert_eq!(shown["components"][0]["component"], "syncthing");
        assert_eq!(shown["components"][0]["reason"], "hash_mismatch");
        assert!(shown["message"]
            .as_str()
            .is_some_and(|m| m.contains("already installed")));
        assert!(snapshot["core"]["awaiting_update"].is_null());
        assert!(!record_dist_check(&state, DistTree::Vendor, Vec::new()));
        assert!(
            local_versions_snapshot(&state, InstallationVersionsAsk::default())["vendor"]
                ["awaiting_update"]
                .is_null()
        );
    }

    /// FINDINGS A-189: every caller of `ensure_blob_sync_runtime` names its policy. Only the vendor
    /// update and an ingress join's setup on the motherbee are strict; the start, the watchdog and
    /// the sync probes keep the installed Syncthing.
    #[test]
    fn only_the_vendor_update_and_an_ingress_join_stop_on_a_vendor_that_does_not_match() {
        let src = include_str!("sy_orchestrator.rs");
        let body = |head: &str| -> &str {
            let rest = &src[src.find(head).unwrap_or_else(|| panic!("{head}"))..];
            &rest[..rest.find("\n}\n").expect("its end")]
        };
        for (head, strict, keep) in [
            ("async fn bootstrap_local(", 0, 1),
            ("async fn watchdog_blob_sync(", 0, 2),
            ("async fn wait_for_syncthing_folder_convergence(", 0, 1),
            ("async fn apply_system_update_local(", 1, 0),
            ("async fn add_ingress_hive_flow(", 1, 0),
        ] {
            let body = body(head);
            assert_eq!(
                body.matches("VendorPolicy::Strict").count(),
                strict,
                "{head}"
            );
            assert_eq!(
                body.matches("VendorPolicy::KeepInstalled").count(),
                keep,
                "{head}"
            );
        }
        // No other caller: those six calls and the function's own head.
        let code = &src[..src.find("#[cfg(test)]\nmod tests {").expect("the tests")];
        assert_eq!(code.matches("ensure_blob_sync_runtime(").count(), 7);
    }

    /// FINDINGS A-190: a join's finalize goes on while dist/vendor is still on its way, with the
    /// Syncthing the bootstrap installed; anything else the vendor step refuses still fails it.
    #[test]
    fn a_finalize_goes_on_while_its_vendor_is_still_arriving_and_only_then() {
        let root = a186_temp_root("a190-vendor");
        let installed = Some(&b"syncthing-2"[..]);
        let manifest_missing =
            "vendor manifest missing at '/var/lib/fluxbee/dist/vendor/manifest.json'";
        let binary_missing =
            "vendor binary 'syncthing' missing at '/var/lib/fluxbee/dist/vendor/syncthing/syncthing'";
        let paths = a189_vendor(&root, b"syncthing-2", Some(b"syncthing-2"), installed);
        fs::remove_file(&paths.manifest).expect("the manifest not there yet");
        assert_eq!(
            vendor_still_arriving(&paths, manifest_missing, true).map(|mismatch| mismatch.reason),
            Some(DistMismatchReason::Missing)
        );
        assert_eq!(
            vendor_still_arriving(&paths, manifest_missing, false),
            None,
            "no Syncthing running to link the peer with"
        );
        assert_eq!(
            vendor_still_arriving(&paths, "syncthing folder markers failed: denied", true),
            None,
            "the step failed on something else"
        );
        let paths = a189_vendor(&root, b"syncthing-2", None, installed);
        assert_eq!(
            vendor_still_arriving(&paths, binary_missing, true).map(|mismatch| mismatch.reason),
            Some(DistMismatchReason::Missing),
            "the binary not there yet"
        );
        let paths = a189_vendor(&root, b"syncthing-2", Some(b"syncthing-x"), installed);
        assert_eq!(
            vendor_still_arriving(&paths, binary_missing, true),
            None,
            "another binary than its manifest says"
        );
        let paths = a189_vendor(&root, b"syncthing-2", None, None);
        assert_eq!(
            vendor_still_arriving(&paths, binary_missing, true),
            None,
            "no Syncthing installed"
        );
        let _ = fs::remove_dir_all(&root);
    }

    /// FINDINGS A-190: the finalize's core step takes A-186's words for a binary still on its way
    /// as pending, as it took the older ones; a binary that is there and wrong still fails it.
