    /// A-101, A-102: a start or a restart writes, before it launches the node and in one write, the
    /// version it launches and `relaunch_on_boot: true` (a stopped node's start sets it again), and
    /// keeps the rest of the config, its mode included: the node reads the version when it starts
    /// (NODE_HELP), status reports it, and a conversion the node makes at boot cannot race the
    /// flag. Recording what the config already says writes nothing, and a config it cannot record
    /// in is the request's answer. That this comes before the launch is
    /// `every_launch_path_records_its_version_before_launching`.
    #[test]
    fn start_and_restart_record_the_launch_before_it() {
        let dir = std::env::temp_dir().join(format!("fluxbee-launch-record-{}", Uuid::new_v4()));
        fs::create_dir_all(&dir).expect("node dir");
        let config_path = dir.join("config.json");
        write_json_atomic(
            &config_path,
            &serde_json::json!({
                "behavior": {"system_prompt": "hi"},
                "_system": {
                    "runtime": "ai.generic",
                    "runtime_version": "0.1.86",
                    "requested_runtime_version": "current",
                    "relaunch_on_boot": false,
                    "config_version": 4,
                    "updated_at_ms": 1
                }
            }),
        )
        .expect("config");

        record_planned_launch("worker1", &ai_pruebas_plan(&config_path)).expect("recorded");
        let config = load_node_effective_config(&config_path).expect("config");
        assert_eq!(config["_system"]["runtime_version"], "0.1.87");
        assert_eq!(config["_system"]["relaunch_on_boot"], true);
        assert_eq!(config["_system"]["requested_runtime_version"], "current");
        assert_eq!(config["_system"]["config_version"], 4);
        assert_eq!(config["behavior"]["system_prompt"], "hi");
        assert!(config["_system"].get("package_path").is_none());
        let mode = fs::metadata(&config_path)
            .expect("stat")
            .permissions()
            .mode();
        assert_eq!(mode & 0o777, 0o600);

        let written = fs::read(&config_path).expect("read");
        record_planned_launch("worker1", &ai_pruebas_plan(&config_path)).expect("recorded");
        assert_eq!(fs::read(&config_path).expect("read"), written);

        let answer = record_planned_launch("worker1", &ai_pruebas_plan(&dir.join("absent.json")))
            .expect_err("a config it cannot record the launch in");
        assert_eq!(answer["error_code"], "CONFIG_WRITE_FAILED");
        assert_eq!(answer["node_name"], "AI.pruebas@worker1");
        assert_eq!(answer["version"], "0.1.87");

        let _ = fs::remove_dir_all(dir);
    }

    /// A package node that moves to another version of its package gets that version's
    /// `package_path`, where the WF engine reads its definition; one that keeps its version keeps
    /// the `package_path` its binder wrote.
    #[test]
    fn a_package_node_that_moves_gets_its_new_package_path() {
        let dir = std::env::temp_dir().join(format!("fluxbee-launch-record-{}", Uuid::new_v4()));
        fs::create_dir_all(&dir).expect("node dir");
        let config_path = dir.join("config.json");
        let old_path = runtime_package_dir("wf.invoice", "7").display().to_string();
        write_json_atomic(
            &config_path,
            &serde_json::json!({
                "_system": {
                    "runtime": "wf.invoice",
                    "runtime_version": "7",
                    "requested_runtime_version": "current",
                    "runtime_base": "wf.engine",
                    "package_path": old_path,
                    "relaunch_on_boot": true
                }
            }),
        )
        .expect("config");
        let plan = |resolved: &str| ManagedNodeLaunchPlan {
            node: PersistedManagedNode {
                node_name: "WF.invoice@worker1".to_string(),
                kind: "WF".to_string(),
                runtime: "wf.invoice".to_string(),
                runtime_version: "7".to_string(),
                requested_runtime_version: "current".to_string(),
                config_path: config_path.clone(),
                relaunch_on_boot: true,
            },
            unit: unit_from_node_name("WF.invoice@worker1"),
            runtime_key: "wf.invoice".to_string(),
            resolved_version: resolved.to_string(),
            requested_version: "current".to_string(),
            entrypoint: RuntimeSpawnEntrypoint {
                script_runtime: "wf.engine".to_string(),
                script_version: "0.1.88".to_string(),
                script_path: runtime_start_script("wf.engine", "0.1.88"),
                runtime_base: Some("wf.engine".to_string()),
            },
            tenant: None,
        };

        record_planned_launch("worker1", &plan("7")).expect("recorded");
        let config = load_node_effective_config(&config_path).expect("config");
        assert_eq!(config["_system"]["package_path"], old_path.as_str());

        record_planned_launch("worker1", &plan("8")).expect("recorded");
        let config = load_node_effective_config(&config_path).expect("config");
        assert_eq!(config["_system"]["runtime_version"], "8");
        assert_eq!(
            config["_system"]["package_path"],
            runtime_package_dir("wf.invoice", "8").display().to_string()
        );
        assert_eq!(config["_system"]["requested_runtime_version"], "current");

        let _ = fs::remove_dir_all(dir);
    }

    /// A-101, A-102: every path that launches a node records what it launches in the node's
    /// config before launching it: run in the config it creates, start and restart, and the
    /// reconcile after its preflight, so it never records a version it then cannot launch. Start
    /// and restart write nothing after the launch. Pinned by reading the source, since the
    /// property is one of order.
    #[test]
    fn every_launch_path_records_its_version_before_launching() {
        let src = include_str!("sy_orchestrator.rs");
        let body = |name: &str| {
            let start = src.find(name).expect(name);
            let end = src[start..]
                .find("\n}\n")
                .map(|o| start + o)
                .expect("its end");
            &src[start..end]
        };
        let in_order = |name: &str, marks: &[&str]| {
            let body = body(name);
            let at: Vec<usize> = marks
                .iter()
                .map(|mark| body.find(mark).unwrap_or_else(|| panic!("{name}: {mark}")))
                .collect();
            assert!(
                at.windows(2).all(|w| w[0] < w[1]),
                "{name}: {marks:?} at {at:?}"
            );
        };
        in_order(
            "async fn run_node_flow(",
            &["ensure_node_effective_config_on_spawn(", "execute_on_hive("],
        );
        in_order(
            "async fn start_or_restart_node_flow(",
            &[
                "managed_node_launch_plan(",
                "tenant_gate_refusal(",
                "record_planned_launch(",
                "managed_node_restart_command(",
                "execute_on_hive(",
            ],
        );
        let flow = body("async fn start_or_restart_node_flow(");
        let launch = flow.find("execute_on_hive(").expect("the launch");
        assert!(
            !flow[launch..].contains("set_node_relaunch_on_boot("),
            "the relaunch flag is written before the launch (A-102)"
        );
        in_order(
            "async fn reconcile_persisted_custom_nodes(",
            &[
                "try_lock_node(",
                "persisted_managed_node_from_config_value(",
                "reconcile_step(",
                "if let Some(payload) = preflight_error",
                "if let Err(err) = persist_node_launch(",
                "clear_stale_transient_unit(",
                "execute_on_hive(",
            ],
        );
    }

    /// A pass decides on the manifest as it is under each node's lock, and two passes never run at
    /// once: the boot's waits for the pass, and the loop skips a tick while the boot's holds it. A
    /// copy of the manifest read earlier could move a node back to the version an older one named.
    /// Run, start and restart check the readiness the reconcile waits for (FINDINGS A-39). Pinned by
    /// reading the source, since the properties are ones of order.
    #[test]
    fn a_pass_decides_on_the_manifest_under_the_nodes_lock_and_passes_never_overlap() {
        let src = include_str!("sy_orchestrator.rs");
        let body = |name: &str| {
            let start = src.find(name).expect(name);
            let end = src[start..]
                .find("\n}\n")
                .map(|o| start + o)
                .expect("its end");
            &src[start..end]
        };
        let in_order = |name: &str, marks: &[&str]| {
            let body = body(name);
            let at: Vec<usize> = marks
                .iter()
                .map(|mark| body.find(mark).unwrap_or_else(|| panic!("{name}: {mark}")))
                .collect();
            assert!(
                at.windows(2).all(|w| w[0] < w[1]),
                "{name}: {marks:?} at {at:?}"
            );
        };
        in_order(
            "async fn reconcile_persisted_custom_nodes(",
            &[
                "try_lock_node(",
                "load_runtime_manifest_result(",
                "reconcile_step(",
            ],
        );
        let pass = body("async fn reconcile_persisted_custom_nodes(");
        assert_eq!(
            pass.matches("load_runtime_manifest_result(").count(),
            1,
            "one manifest, read under the node's lock"
        );
        in_order(
            "async fn finish_bootstrap(",
            &[
                "reconcile_pass.lock().await",
                "reconcile_persisted_custom_nodes(",
            ],
        );
        in_order(
            "async fn run_managed_runtime_reconcile_loop(",
            &[
                "reconcile_pass.try_lock()",
                "reconcile_persisted_custom_nodes(",
            ],
        );
        in_order(
            "fn managed_node_launch_plan(",
            &[
                "node_package_files_preflight(",
                "runtime_readiness_refusal(",
            ],
        );
        in_order(
            "async fn run_node_flow(",
            &[
                "runtime_spawn_preflight_with_manifest(",
                "runtime_readiness_refusal(",
                "ensure_node_identity_registered(",
                "execute_on_hive(",
            ],
        );
        in_order(
            "async fn start_or_restart_node_flow(",
            &["managed_node_launch_plan(", "execute_on_hive("],
        );
    }

    /// A restart has to RECREATE the unit when the entrypoint's path changed.
    ///
    /// `systemctl restart` reruns the ExecStart the unit already has, and that path carries the
    /// runtime's version inside. So restarting after publishing a new version relaunched the OLD
    /// binary, while the reply told the operator the new version. A version promised and not
    /// applied: the shape of U-1.
    ///
    /// Measured live: `restart_node` returned `version: 0.1.14` and the process was still
    /// `/var/lib/fluxbee/dist/runtimes/io.slack/0.1.13/bin/io-slack`.
    #[test]
    fn a_restart_recreates_the_unit_when_the_entrypoint_path_changed() {
        let plan = ManagedNodeLaunchPlan {
            node: PersistedManagedNode {
                requested_runtime_version: "current".to_string(),
                node_name: "IO.slack.default@motherbee".to_string(),
                kind: "IO".to_string(),
                runtime: "io.slack".to_string(),
                runtime_version: "0.1.14".to_string(),
                config_path: PathBuf::from("/tmp/config.json"),
                relaunch_on_boot: true,
            },
            unit: unit_from_node_name("IO.slack.default@motherbee"),
            runtime_key: "io.slack".to_string(),
            resolved_version: "0.1.14".to_string(),
            requested_version: "current".to_string(),
            entrypoint: RuntimeSpawnEntrypoint {
                script_runtime: "io.slack".to_string(),
                script_version: "0.1.14".to_string(),
                script_path: "/var/lib/fluxbee/dist/runtimes/io.slack/0.1.14/bin/start.sh"
                    .to_string(),
                runtime_base: None,
            },
            tenant: None,
        };
        let state = sample_orchestrator_state_for_tests();
        let cmd = managed_node_restart_command(&state, &plan, true);

        assert!(
            cmd.contains("ExecStart") && cmd.contains("0.1.14/bin/start.sh"),
            "it has to compare the live ExecStart against the planned path: {cmd}"
        );
        assert!(
            cmd.contains("systemctl stop") && cmd.contains("systemd-run"),
            "when they differ, it has to stop the unit and recreate it: {cmd}"
        );
        assert!(
            cmd.contains("systemctl restart"),
            "when they already match, restarting in place is enough: {cmd}"
        );
        assert!(
            cmd.contains("grep -qxF 'FLUXBEE_NODE_RUNTIME_VERSION=0.1.14'"),
            "in place only when the unit carries the planned version too: {cmd}"
        );
    }

    /// Starting/restarting a node has to resolve the INTENT, not the stored answer.
    ///
    /// It is the same rule U-10 put in the orchestrator's boot, and that this path lacked: a node
    /// with `_system.requested_runtime_version = "current"` was launched again on its last
    /// CONCRETE version. Real effect: publishing a new runtime and restarting the node never
    /// picked it up, so the "growth = publish + update, no new .deb" model did not work for a node
    /// already running, and on top of that the reply returned the old version as
    /// `requested_version`.
    ///
    /// It is pinned by reading the source because the property is one of ORDER: computing the
    /// intent has to come BEFORE the resolution, and the resolution has to use it.
    #[test]
    fn starting_a_node_resolves_the_intent_not_the_stored_version() {
        let src = include_str!("sy_orchestrator.rs");
        let start = src
            .find("fn managed_node_launch_plan(")
            .expect("managed_node_launch_plan");
        let body = &src[start..];
        let end = body.find("\n}").expect("its end");
        let body = &body[..end];

        let intent = body
            .find("node.follows_current()")
            .expect("it has to consult the node's INTENT");
        let resolve = body
            .find("resolve_runtime_version(&manifest, &runtime_key, &requested_version)")
            .expect("the resolution has to use the intent, not node.runtime_version");
        assert!(
            intent < resolve,
            "the intent is computed before resolving, not after"
        );
        assert!(
            !body.contains(
                "resolve_runtime_version(&manifest, &runtime_key, &node.runtime_version)"
            ),
            "resolving the stored CONCRETE version re-pins a node that follows current"
        );
    }

    /// IO.blob and IO.cloud are MANAGED runtimes, with no systemd unit of their own.
    ///
    /// They no longer have their own systemd unit: the orchestrator is their only owner (it
    /// instantiates them through `run_node` and relaunches them in `reconcile`), and they are
    /// configured by CONFIG_SET/GET. That is why the adoption sweep HAS to relaunch them: it is
    /// their only way to start, as for any runtime. The double-owner guard
    /// (`managed_spawn_disallowed_reason`) blocks SY.* and RT.gateway; no managed runtime has a
    /// systemd unit competing for the process.
    #[test]
    fn io_blob_and_io_cloud_are_adopted_as_managed_runtimes() {
        for name in [
            "IO.cloud@motherbee",
            "IO.blob@motherbee",
            "io.cloud@motherbee",
            "IO.slack.default@motherbee",
            "AI.chat@motherbee",
            "WF.router@motherbee",
        ] {
            assert!(
                managed_spawn_disallowed_reason(name).is_none(),
                "{name} is a managed runtime: the boot pass HAS to relaunch it"
            );
            assert!(managed_reconcile_candidate_allowed(name));
        }
    }

    /// U-7, and the residual that outlived its fix.
    ///
    /// Motherbee does not sync to itself, so it never declares `fluxbee-dist-core-motherbee`.
    /// Asking syncthing about it returns 404 — which is how the watchdog logged a warn every five
    /// seconds forever. The watchdog was fixed by routing it through `dist_sync_folders_for_hive`,
    /// but the `dist` sync-hint resolver was still on `dist_sync_folders_for_role`, and there the
    /// same 404 is worse than noisy: a hint fans out over these ids and the first non-ok wins, so
    /// the undeclared folder failed the whole hint — the exact thing `update category=core` waits
    /// on.
    #[test]
    fn motherbee_never_resolves_a_dist_folder_it_does_not_declare() {
        let dist = sample_dist_config();
        let blob_root = sample_blob_config().path;
        let carried = dist_sync_folders_for_hive(&dist, &blob_root, HiveRole::Motherbee, true);
        let ids: Vec<&str> = carried.iter().map(|f| f.id.as_str()).collect();

        assert!(
            !ids.iter().any(|id| id.contains("motherbee")),
            "motherbee does not sync to itself; asking syncthing for its own core folder is a 404: {ids:?}"
        );
        for role in ROLE_CORE_DIST_ROLES {
            let expected = format!("{SYNCTHING_FOLDER_DIST_CORE_PREFIX}{}", role.as_str());
            assert!(
                ids.contains(&expected.as_str()),
                "motherbee serves one core folder per spoke role; {expected} missing from {ids:?}"
            );
        }

        // A spoke carries only its own, and must NOT be handed its siblings' folders.
        let spoke = dist_sync_folders_for_hive(&dist, &blob_root, HiveRole::Ingress, false);
        let spoke_ids: Vec<&str> = spoke.iter().map(|f| f.id.as_str()).collect();
        assert!(spoke_ids.contains(&format!("{SYNCTHING_FOLDER_DIST_CORE_PREFIX}ingress").as_str()));
        assert!(
            !spoke_ids
                .iter()
                .any(|id| id.ends_with("worker") || id.ends_with("egress")),
            "a spoke must not be asked to settle another role's folder: {spoke_ids:?}"
        );
    }

    /// The path asymmetry is the trick that keeps every spoke-side constant untouched:
    /// motherbee serves `dist/core/<role>`, the spoke receives it as its own `dist/core`, and
    /// both ends agree on the folder id.
    #[test]
    fn core_folder_path_is_role_scoped_on_motherbee_and_plain_on_the_spoke() {
        let dist = sample_dist_config();
        let blob_root = sample_blob_config().path;
        let on_mb = dist_sync_folders_for_role(&dist, &blob_root, HiveRole::Ingress, true);
        let on_spoke = dist_sync_folders_for_role(&dist, &blob_root, HiveRole::Ingress, false);

        assert_eq!(on_mb[0].id, on_spoke[0].id);
        assert_eq!(
            on_mb[0].path,
            PathBuf::from("/var/lib/fluxbee/dist/core/ingress")
        );
        assert_eq!(
            on_spoke[0].path,
            PathBuf::from("/var/lib/fluxbee/dist/core")
        );
    }

    /// REGRESSION (U-7): motherbee does not sync to itself, so it NEVER declares
    /// `fluxbee-dist-core-motherbee`. The health watchdog asked about it anyway (it derived the set
    /// from its own role instead of from the same rule as the declaration) and got a 404 every five
    /// seconds, forever. The declaration, the `.stfolder` markers and the health check must all
    /// come from `dist_sync_folders_for_hive`.
    #[test]
    fn motherbee_never_polls_a_core_folder_for_itself() {
        let dist = sample_dist_config();
        let blob_root = sample_blob_config().path;
        let ids: Vec<String> =
            dist_sync_folders_for_hive(&dist, &blob_root, HiveRole::Motherbee, true)
                .into_iter()
                .map(|f| f.id)
                .collect();
        assert!(
            !ids.iter().any(|id| id.ends_with("motherbee")),
            "motherbee must neither declare nor query a core folder of its own; got {ids:?}"
        );
        // It does serve the three spoke roles, plus vendor and runtimes.
        for role in ["worker", "ingress", "egress"] {
            assert!(ids.contains(&format!("{SYNCTHING_FOLDER_DIST_CORE_PREFIX}{role}")));
        }
        assert!(ids.contains(&SYNCTHING_FOLDER_DIST_VENDOR_ID.to_string()));
        assert!(ids.contains(&SYNCTHING_FOLDER_DIST_RUNTIMES_ID.to_string()));
        assert!(ids.contains(&SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID.to_string()));
    }

    /// The shared id (vendor) is declared ONCE even though all three roles use it.
    #[test]
    fn shared_dist_folders_are_declared_once() {
        let dist = sample_dist_config();
        let blob_root = sample_blob_config().path;
        let ids: Vec<String> =
            dist_sync_folders_for_hive(&dist, &blob_root, HiveRole::Motherbee, true)
                .into_iter()
                .map(|f| f.id)
                .collect();
        let mut sorted = ids.clone();
        sorted.sort();
        sorted.dedup();
        assert_eq!(sorted.len(), ids.len(), "duplicate ids in {ids:?}");
    }

    /// A spoke carries only its own: its core, vendor, and runtimes only if it is a worker.
    #[test]
    fn a_spoke_carries_only_its_own_dist_folders() {
        let dist = sample_dist_config();
        let blob_root = sample_blob_config().path;
        for (role, wants_runtimes) in [
            (HiveRole::Worker, true),
            (HiveRole::Ingress, false),
            (HiveRole::Egress, false),
        ] {
            let ids: Vec<String> = dist_sync_folders_for_hive(&dist, &blob_root, role, false)
                .into_iter()
                .map(|f| f.id)
                .collect();
            assert!(ids.contains(&format!(
                "{SYNCTHING_FOLDER_DIST_CORE_PREFIX}{}",
                role.as_str()
            )));
            // and no other role's
            for other in ["worker", "ingress", "egress"] {
                if other != role.as_str() {
                    assert!(
                        !ids.contains(&format!("{SYNCTHING_FOLDER_DIST_CORE_PREFIX}{other}")),
                        "{} must not carry the folder of {other}",
                        role.as_str()
                    );
                }
            }
            assert_eq!(
                ids.contains(&SYNCTHING_FOLDER_DIST_RUNTIMES_ID.to_string()),
                wants_runtimes,
                "runtimes for {}",
                role.as_str()
            );
            assert_eq!(
                ids.contains(&SYNCTHING_FOLDER_DIST_AGENT_ASSETS_ID.to_string()),
                wants_runtimes,
                "agent assets for {}",
                role.as_str()
            );
        }
    }

    /// Every dist folder must own a disjoint subtree. Two syncthing folders over one tree are
    /// accepted silently by the daemon and then fight over a single index — the mechanism
    /// behind the recorded `runtimes/ai.common/0.1.2` deletion.
    #[test]
    fn dist_folders_never_overlap() {
        let dist = sample_dist_config();
        let blob = sample_blob_config();
        let blob_root = blob.path.clone();
        for role in [HiveRole::Worker, HiveRole::Ingress, HiveRole::Egress] {
            for is_mb in [true, false] {
                let mut folders = dist_sync_folders_for_role(&dist, &blob_root, role, is_mb);
                // The agent assets sit beside the blob folders, under blob/, itself no folder:
                // a writer's temporary file there never syncs.
                for (id, path) in [
                    (SYNCTHING_FOLDER_BLOB_ID, blob_sync_folder_path(&blob)),
                    (
                        SYNCTHING_FOLDER_BLOB_PUBLIC_ID,
                        blob_public_sync_folder_path(&blob),
                    ),
                ] {
                    folders.push(DistSyncFolder {
                        id: id.to_string(),
                        path,
                        label: "blob",
                    });
                }
                assert!(folders.iter().all(|f| f.path != blob_root));
                for (i, a) in folders.iter().enumerate() {
                    for b in folders.iter().skip(i + 1) {
                        assert_ne!(a.id, b.id, "duplicate folder id for {:?}", role);
                        assert!(
                            !a.path.starts_with(&b.path) && !b.path.starts_with(&a.path),
                            "folders {} and {} overlap on disk ({} vs {})",
                            a.id,
                            b.id,
                            a.path.display(),
                            b.path.display()
                        );
                    }
                }
            }
        }
    }

