    #[test]
    fn apply_runtime_retention_preserves_runtime_referenced_by_persisted_instance() {
        let root = std::env::temp_dir().join(format!("fluxbee-retention-test-{}", Uuid::new_v4()));
        let runtimes_root = root.join("dist").join("runtimes");
        let nodes_root = root.join("nodes");

        let kept_runtime_dir = runtimes_root.join("ai.chat.test").join("1.0.0");
        fs::create_dir_all(&kept_runtime_dir).expect("create kept runtime dir");
        fs::write(kept_runtime_dir.join("marker"), "keep").expect("write kept marker");

        let pruned_runtime_dir = runtimes_root.join("ai.prune.test").join("1.0.0");
        fs::create_dir_all(&pruned_runtime_dir).expect("create pruned runtime dir");
        fs::write(pruned_runtime_dir.join("marker"), "prune").expect("write pruned marker");

        let node_dir = nodes_root.join("AI").join("AI.chat@motherbee");
        fs::create_dir_all(&node_dir).expect("create node dir");
        fs::write(
            node_dir.join("config.json"),
            serde_json::json!({
                "_system": {
                    "runtime": "ai.chat.test",
                    "runtime_version": "1.0.0",
                    "relaunch_on_boot": true
                }
            })
            .to_string(),
        )
        .expect("write config");

        let manifest = RuntimeManifest {
            schema_version: 1,
            version: 1710000000000,
            updated_at: Some("2026-03-20T00:00:00Z".to_string()),
            runtimes: serde_json::json!({}),
            hash: None,
        };

        let stats = apply_runtime_retention_with_roots_and_protection(
            &manifest,
            &runtimes_root,
            &nodes_root,
            &HashMap::new(),
        )
        .expect("retention should succeed");

        assert!(
            kept_runtime_dir.exists(),
            "persisted runtime should be kept"
        );
        assert!(
            !pruned_runtime_dir.exists(),
            "unreferenced runtime should be pruned"
        );
        assert_eq!(stats.removed_runtime_dirs, 1);

        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn apply_runtime_retention_with_roots_and_protection_keeps_temporarily_protected_version() {
        let root =
            std::env::temp_dir().join(format!("fluxbee-retention-protected-{}", Uuid::new_v4()));
        let runtimes_root = root.join("runtimes");
        let nodes_root = root.join("nodes");
        let protected_runtime_dir = runtimes_root.join("ai.common").join("0.1.2");
        let sibling_runtime_dir = runtimes_root.join("ai.common").join("0.1.1");

        fs::create_dir_all(&protected_runtime_dir).expect("create protected runtime dir");
        fs::create_dir_all(&sibling_runtime_dir).expect("create sibling runtime dir");
        fs::create_dir_all(&nodes_root).expect("create nodes root");

        let manifest = RuntimeManifest {
            schema_version: 1,
            version: 1710000000000,
            updated_at: Some("2026-03-20T00:00:00Z".to_string()),
            runtimes: serde_json::json!({}),
            hash: None,
        };

        let mut protected_keep: HashMap<String, HashSet<String>> = HashMap::new();
        protected_keep
            .entry("ai.common".to_string())
            .or_default()
            .insert("0.1.2".to_string());

        let stats = apply_runtime_retention_with_roots_and_protection(
            &manifest,
            &runtimes_root,
            &nodes_root,
            &protected_keep,
        )
        .expect("retention with protection should succeed");

        assert!(
            protected_runtime_dir.exists(),
            "protected version should be kept during temporary retention window"
        );
        assert!(
            !sibling_runtime_dir.exists(),
            "unprotected sibling version should still be pruned"
        );
        assert_eq!(stats.protected_runtime_dirs, 1);
        assert_eq!(stats.protected_version_dirs, 1);
        assert_eq!(stats.removed_version_dirs, 1);

        let _ = fs::remove_dir_all(&root);
    }

