    /// An SY node runs as its packaged unit and the router as `rt-gateway`, never as a
    /// `fluxbee-node-*` unit; a core node this hive's role does not run is not here.
    #[test]
    fn core_nodes_take_their_lifecycle_from_their_packaged_unit() {
        let role = [
            "SY.config.routes".to_string(),
            "SY.storage".to_string(),
            "SY.frontdesk.gov".to_string(),
        ];
        let unit = |name: &str| node_unit_for(name, "RT.gateway@motherbee", &role);
        assert_eq!(
            unit("SY.storage@motherbee"),
            Some(NodeUnit::Core("sy-storage".to_string()))
        );
        assert_eq!(
            unit("SY.config.routes@motherbee"),
            Some(NodeUnit::Core("sy-config-routes".to_string()))
        );
        assert_eq!(
            unit("SY.frontdesk.gov@motherbee"),
            Some(NodeUnit::Core("sy-frontdesk-gov".to_string()))
        );
        // The orchestrator runs on every role without being in the list.
        assert_eq!(
            unit("SY.orchestrator@motherbee"),
            Some(NodeUnit::Core("sy-orchestrator".to_string()))
        );
        assert_eq!(unit("SY.edge@motherbee"), None);
        assert_eq!(
            unit("RT.gateway@motherbee"),
            Some(NodeUnit::Core("rt-gateway".to_string()))
        );
        assert_eq!(
            unit("RT.gateway.stream@motherbee"),
            Some(NodeUnit::Core("rt-gateway".to_string()))
        );
        assert_eq!(unit("RT.other@motherbee"), None);
        assert_eq!(
            unit("AI.sales@motherbee"),
            Some(NodeUnit::Managed(
                "fluxbee-node-AI.sales-motherbee".to_string()
            ))
        );

        let core = NodeUnit::Core("sy-storage".to_string());
        let managed = NodeUnit::Managed("fluxbee-node-AI.sales-motherbee".to_string());
        assert_eq!(
            node_lifecycle_state(&core, true, false, true, false),
            "RUNNING"
        );
        assert_eq!(
            node_lifecycle_state(&core, true, false, false, false),
            "STARTING"
        );
        assert_eq!(
            node_lifecycle_state(&core, false, true, false, false),
            "FAILED"
        );
        assert_eq!(
            node_lifecycle_state(&core, false, false, false, false),
            "STOPPED"
        );
        assert_eq!(
            node_lifecycle_state(&managed, false, false, false, true),
            "STOPPED"
        );
        assert_eq!(
            node_lifecycle_state(&managed, false, false, false, false),
            "UNKNOWN"
        );
    }

    /// The router's own name is no node of its LSA: it shows itself by keeping its hive's entry
    /// fresh, so a running router reads RUNNING, not STARTING forever.
    #[test]
    fn the_router_shows_itself_by_a_fresh_entry_for_its_hive() {
        let entry = |hive: &str, last_updated: u64, flags: u16| {
            let mut hive_id = [0u8; 64];
            hive_id[..hive.len()].copy_from_slice(hive.as_bytes());
            RemoteHiveEntry {
                hive_id,
                hive_id_len: hive.len() as u16,
                router_uuid: [0u8; 16],
                router_name: [0u8; 64],
                router_name_len: 0,
                last_lsa_seq: 0,
                last_updated,
                flags,
                node_count: 0,
                route_count: 0,
                vpn_count: 0,
                tap_count: 0,
            }
        };
        let now = 10_000_000;
        assert!(lsa_hive_entry_fresh(
            &[entry("worker1", now - 1_000, 0)],
            "worker1",
            now
        ));
        assert!(!lsa_hive_entry_fresh(
            &[entry("worker1", now - HEARTBEAT_STALE_MS - 1, 0)],
            "worker1",
            now
        ));
        assert!(!lsa_hive_entry_fresh(
            &[entry("worker1", now, FLAG_STALE)],
            "worker1",
            now
        ));
        assert!(!lsa_hive_entry_fresh(
            &[entry("motherbee", now, 0)],
            "worker1",
            now
        ));
        assert!(!lsa_hive_entry_fresh(&[], "worker1", now));
    }

    /// The motherbee takes blob/agent-assets back, as it does the other blob trees, only where hard
    /// links to another user's files are protected.
    #[test]
    fn the_motherbee_takes_agent_assets_back_only_where_hard_links_are_protected() {
        let src = include_str!("sy_orchestrator.rs");
        let start = src.find("fn ensure_dirs(").expect("ensure_dirs");
        let body = &src[start..start + src[start..].find("\n}\n").expect("its end")];
        assert!(
            body.contains("HiveRole::Motherbee if can_take_back => Some(ensure_root_owned_tree(")
        );
    }

    /// A status read of a core node takes it from its unit and creates no state for it: no status
    /// version is kept under nodes/SY. A core node this hive's role does not run is not found.
    #[tokio::test]
    async fn a_core_node_status_reads_its_unit_and_writes_nothing() {
        let state = sample_orchestrator_state_for_tests();
        let status = get_node_status_flow(
            &state,
            &serde_json::json!({ "node_name": "SY.timer@motherbee" }),
        )
        .await;
        assert_eq!(status["status"], "ok", "{status}");
        let node = &status["node_status"];
        assert_eq!(node["process"]["unit"], "sy-timer");
        assert_ne!(node["lifecycle_state"], "UNKNOWN");
        assert_eq!(node["config"], serde_json::json!({ "managed": false }));
        assert_eq!(node["state"], serde_json::json!({ "managed": false }));
        assert_eq!(node["status_version"], serde_json::Value::Null);

        let elsewhere = get_node_status_flow(
            &state,
            &serde_json::json!({ "node_name": "SY.edge@motherbee" }),
        )
        .await;
        assert_eq!(elsewhere["error_code"], "NODE_NOT_FOUND");
    }

    /// A node's NODE_HELP_RESPONSE as docs/agent-tools-v1.md §3.3 shapes it, with one card.
    fn node_help_response(node_name: &str) -> serde_json::Value {
        serde_json::json!({
            "status": "ok",
            "node_name": node_name,
            "runtime": "ai.generic",
            "runtime_version": "0.1.86",
            "tools": [{
                "name": "generate_csv_artifact",
                "summary": "Write a CSV file and return its blob reference.",
                "when_to_use": "When the answer is a table the person opens in a spreadsheet.",
                "limits": ["One file per call."],
                "present_when": "always",
                "input": {
                    "type": "object",
                    "properties": { "rows": { "type": "array" } },
                    "required": ["rows"],
                },
                "output": {
                    "type": "object",
                    "properties": { "blob_ref": { "type": "object" } },
                },
                "errors": [{ "code": "too_large", "meaning": "the file passes the size limit" }],
            }],
        })
    }

    /// docs/agent-tools-v1.md §3.3: `node_help` travels as `get_node_status` does. For a node of
    /// another hive the motherbee forwards NODE_HELP to that hive's orchestrator and answers with
    /// what that hive says: the node's cards, or no help and why.
    #[tokio::test]
    async fn node_help_for_a_node_of_another_hive_is_asked_there() {
        let state = Arc::new(sample_orchestrator_state_for_tests());
        let (client, mut harness) = attach_test_rpc(&state);
        let admin_rx = client
            .take_command_receiver(RPC_CH_ADMIN)
            .await
            .expect("admin receiver");
        {
            let state = Arc::clone(&state);
            let client = Arc::clone(&client);
            tokio::spawn(async move {
                run_admin_worker(state, client, admin_rx).await;
            });
        }
        let node = "AI.sales@worker1";
        let described = serde_json::json!({
            "status": "ok",
            "node_name": node,
            "help": node_help_response(node),
            "reason": null,
        });
        let silent = serde_json::json!({
            "status": "ok",
            "node_name": node,
            "help": null,
            "reason": "the node did not answer NODE_HELP within 3 s",
        });
        for (trace, answer) in [("help-described", described), ("help-silent", silent)] {
            harness
                .inject(test_admin_command(
                    trace,
                    "node_help",
                    serde_json::json!({ "node_name": node, "target": "worker1" }),
                ))
                .await
                .expect("inject admin command");
            let forwarded = time::timeout(Duration::from_secs(1), harness.next_outgoing())
                .await
                .expect("NODE_HELP forwarded")
                .expect("forwarded message");
            assert_unicast_destination(&forwarded.routing.dst, "SY.orchestrator@worker1");
            assert_eq!(forwarded.meta.msg_type, SYSTEM_KIND);
            assert_eq!(forwarded.meta.msg.as_deref(), Some("NODE_HELP"));
            assert_eq!(forwarded.payload["node_name"], node);
            assert_eq!(forwarded.payload["target"], "worker1");
            harness
                .inject(test_response_for(
                    &forwarded,
                    SYSTEM_KIND,
                    "NODE_HELP_RESPONSE",
                    answer.clone(),
                ))
                .await
                .expect("inject the hive's answer");
            let reply = time::timeout(Duration::from_secs(1), harness.next_outgoing())
                .await
                .expect("admin reply emitted")
                .expect("admin reply");
            assert_eq!(reply.meta.msg_type, ADMIN_KIND);
            assert_eq!(reply.meta.action.as_deref(), Some("node_help"));
            assert_eq!(reply.routing.trace_id, trace);
            assert_eq!(reply.payload, answer);
        }
    }

    /// On the node's own hive, NODE_HELP decides whether the node is here as a status read does.
    /// A core node of this role answers ok at once, with no help and why: no core node describes
    /// itself; a node that is not here answers NODE_NOT_FOUND. Only an orchestrator or the same
    /// hive's admin may send it: the local guard (SO-05) refuses a node asking for another's.
    #[tokio::test]
    async fn node_help_on_the_nodes_hive_says_why_a_node_gives_no_help() {
        let state = Arc::new(sample_orchestrator_state_for_tests());
        let (client, mut harness) = attach_test_rpc(&state);
        let system_rx = client
            .take_command_receiver(RPC_CH_SYSTEM)
            .await
            .expect("system receiver");
        {
            let state = Arc::clone(&state);
            let client = Arc::clone(&client);
            tokio::spawn(async move {
                run_system_worker(state, client, system_rx).await;
            });
        }
        let ask = |trace: &str, node_name: &str, origin: &str| {
            let mut msg = test_system_message(
                trace,
                "NODE_HELP",
                serde_json::json!({ "node_name": node_name, "target": "motherbee" }),
            );
            msg.routing.src_l2_name = Some(origin.to_string());
            msg
        };
        let orchestrator = "SY.orchestrator@motherbee";

        harness
            .inject(ask("help-core", "SY.timer@motherbee", orchestrator))
            .await
            .expect("inject NODE_HELP");
        let reply = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("NODE_HELP answered")
            .expect("reply");
        assert_eq!(reply.meta.msg.as_deref(), Some("NODE_HELP_RESPONSE"));
        assert_eq!(reply.routing.trace_id, "help-core");
        assert_eq!(reply.payload["status"], "ok", "{}", reply.payload);
        assert_eq!(reply.payload["node_name"], "SY.timer@motherbee");
        assert!(reply.payload["help"].is_null());
        assert_eq!(
            reply.payload["reason"],
            "the node is a core node: only ai.generic nodes answer NODE_HELP"
        );

        for (trace, node) in [
            ("help-elsewhere", "SY.edge@motherbee"),
            ("help-ghost", "AI.ghost@motherbee"),
        ] {
            harness
                .inject(ask(trace, node, orchestrator))
                .await
                .expect("inject NODE_HELP");
            let reply = time::timeout(Duration::from_secs(1), harness.next_outgoing())
                .await
                .expect("NODE_HELP answered")
                .expect("reply");
            assert_eq!(reply.routing.trace_id, trace);
            assert_eq!(reply.payload["error_code"], "NODE_NOT_FOUND", "{node}");
        }

        harness
            .inject(ask(
                "help-rogue",
                "SY.timer@motherbee",
                "AI.sales@motherbee",
            ))
            .await
            .expect("inject NODE_HELP");
        let reply = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("refusal emitted")
            .expect("reply");
        assert_eq!(reply.meta.msg.as_deref(), Some("NODE_HELP_RESPONSE"));
        assert_eq!(reply.payload["error_code"], "UNAUTHORIZED");
    }

    /// The node's answer to NODE_HELP: its cards when it says ok, else no help and why. Silence is
    /// no error, and its reason says only that: a busy AI node can miss the deadline too.
    #[test]
    fn a_nodes_answer_to_node_help_is_its_cards_or_why_not() {
        let timeout = Duration::from_secs(NODE_HELP_PROBE_TIMEOUT_SECS);
        let cards = node_help_response("AI.sales@motherbee");
        assert_eq!(
            node_help_from_answer(Ok(cards.clone()), timeout),
            (Some(cards), None)
        );

        let refused = serde_json::json!({
            "status": "error",
            "error_code": "NOT_CONFIGURED",
            "message": "no catalog loaded",
        });
        assert_eq!(
            node_help_from_answer(Ok(refused), timeout),
            (
                None,
                Some(
                    "the node answered NODE_HELP with an error: NOT_CONFIGURED: no catalog loaded"
                        .to_string()
                )
            )
        );
        assert_eq!(
            node_help_from_answer(Ok(serde_json::json!({ "tools": [] })), timeout),
            (
                None,
                Some("the node answered NODE_HELP without status ok".to_string())
            )
        );

        let silent = RpcError::Timeout {
            trace_id: "help-trace".to_string(),
            target: "AI.sales@motherbee".to_string(),
            request_msg: "NODE_HELP".to_string(),
            response_msg: "NODE_HELP_RESPONSE".to_string(),
            timeout_ms: 3_000,
        };
        assert_eq!(
            node_help_from_answer(Err(silent), timeout),
            (
                None,
                Some("the node did not answer NODE_HELP within 3 s".to_string())
            )
        );

        // A runtime from before NODE_HELP answers an unknown verb with something else.
        let other = RpcError::InvalidResponse(
            "unexpected response shape msg_type=system msg=Some(\"CONFIG_RESPONSE\")".to_string(),
        );
        let (help, reason) = node_help_from_answer(Err(other), timeout);
        assert_eq!(help, None);
        let reason = reason.expect("a reason");
        assert!(
            reason.starts_with("no answer to NODE_HELP: invalid response"),
            "{reason}"
        );
    }

    /// Only a node that ai.generic runs is asked for its help, its package's base runtime
    /// included; any other answers at once, and the reason names what runs it.
    #[test]
    fn only_a_node_ai_generic_runs_is_asked_for_its_help() {
        let config = |system: serde_json::Value| serde_json::json!({ "_system": system });
        for asked in [
            config(serde_json::json!({ "runtime": "ai.generic" })),
            config(serde_json::json!({ "runtime": "AI.Generic" })),
            config(serde_json::json!({ "runtime": "ai.billing", "runtime_base": "ai.generic" })),
        ] {
            assert_eq!(
                node_help_unasked_reason(true, Some(&asked)),
                None,
                "{asked}"
            );
        }

        let only = "only ai.generic nodes answer NODE_HELP";
        for (managed, unasked, reason) in [
            (false, None, format!("the node is a core node: {only}")),
            (
                true,
                Some(config(serde_json::json!({ "runtime": "io.slack" }))),
                format!("the node runs io.slack: {only}"),
            ),
            (
                true,
                Some(config(
                    serde_json::json!({ "runtime": "wf.invoice", "runtime_base": "wf.engine" }),
                )),
                format!("the node runs wf.engine: {only}"),
            ),
            (
                true,
                Some(config(serde_json::json!({ "runtime": " " }))),
                format!("the node has no config.json that names its runtime: {only}"),
            ),
            (
                true,
                None,
                format!("the node has no config.json that names its runtime: {only}"),
            ),
        ] {
            assert_eq!(
                node_help_unasked_reason(managed, unasked.as_ref()),
                Some(reason)
            );
        }
    }

    /// `node_help` runs in its own task, which answers SY.admin itself: while another hive is asked
    /// for a node's help, the admin worker goes on, and `hive_status` (SY.admin's 5 s) answers at
    /// once.
    #[tokio::test]
    async fn node_help_leaves_the_admin_worker_free() {
        let state = Arc::new(sample_orchestrator_state_for_tests());
        let (client, mut harness) = attach_test_rpc(&state);
        let admin_rx = client
            .take_command_receiver(RPC_CH_ADMIN)
            .await
            .expect("admin receiver");
        {
            let state = Arc::clone(&state);
            let client = Arc::clone(&client);
            tokio::spawn(async move {
                run_admin_worker(state, client, admin_rx).await;
            });
        }
        let node = "AI.sales@worker1";
        harness
            .inject(test_admin_command(
                "help-pending",
                "node_help",
                serde_json::json!({ "node_name": node, "target": "worker1" }),
            ))
            .await
            .expect("inject node_help");
        let forwarded = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("NODE_HELP forwarded")
            .expect("forwarded message");
        assert_eq!(forwarded.meta.msg.as_deref(), Some("NODE_HELP"));

        harness
            .inject(test_admin_command(
                "status-meanwhile",
                "hive_status",
                serde_json::json!({}),
            ))
            .await
            .expect("inject hive_status");
        let status = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("hive_status answered while the help is pending")
            .expect("hive_status reply");
        assert_eq!(status.meta.action.as_deref(), Some("hive_status"));
        assert_eq!(status.routing.trace_id, "status-meanwhile");
        assert_eq!(status.payload["status"], "ok");

        let answer = serde_json::json!({
            "status": "ok",
            "node_name": node,
            "help": node_help_response(node),
            "reason": null,
        });
        harness
            .inject(test_response_for(
                &forwarded,
                SYSTEM_KIND,
                "NODE_HELP_RESPONSE",
                answer.clone(),
            ))
            .await
            .expect("inject the hive's answer");
        let reply = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("node_help answered by its task")
            .expect("node_help reply");
        assert_eq!(reply.meta.msg_type, ADMIN_KIND);
        assert_eq!(reply.meta.action.as_deref(), Some("node_help"));
        assert_eq!(reply.routing.trace_id, "help-pending");
        assert_eq!(reply.payload, answer);
    }

    /// NODE_HELP runs in its own task too, which answers with NODE_HELP_RESPONSE: while it waits,
    /// the system worker takes the next message.
    #[tokio::test]
    async fn node_help_leaves_the_system_worker_free() {
        let state = Arc::new(sample_orchestrator_state_for_tests());
        let (client, mut harness) = attach_test_rpc(&state);
        let system_rx = client
            .take_command_receiver(RPC_CH_SYSTEM)
            .await
            .expect("system receiver");
        {
            let state = Arc::clone(&state);
            let client = Arc::clone(&client);
            tokio::spawn(async move {
                run_system_worker(state, client, system_rx).await;
            });
        }
        let from_orchestrator = |trace: &str, msg_name: &str, payload: serde_json::Value| {
            let mut msg = test_system_message(trace, msg_name, payload);
            msg.routing.src_l2_name = Some("SY.orchestrator@motherbee".to_string());
            msg
        };
        harness
            .inject(from_orchestrator(
                "help-pending",
                "NODE_HELP",
                serde_json::json!({ "node_name": "AI.sales@worker1", "target": "worker1" }),
            ))
            .await
            .expect("inject NODE_HELP");
        let forwarded = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("NODE_HELP forwarded")
            .expect("forwarded message");
        assert_unicast_destination(&forwarded.routing.dst, "SY.orchestrator@worker1");

        harness
            .inject(from_orchestrator(
                "status-meanwhile",
                "NODE_STATUS_GET",
                serde_json::json!({ "node_name": "SY.timer@motherbee", "target": "motherbee" }),
            ))
            .await
            .expect("inject NODE_STATUS_GET");
        let status = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("NODE_STATUS_GET answered while the help is pending")
            .expect("status reply");
        assert_eq!(status.meta.msg.as_deref(), Some("NODE_STATUS_GET_RESPONSE"));
        assert_eq!(status.routing.trace_id, "status-meanwhile");

        let silent = serde_json::json!({
            "status": "ok",
            "node_name": "AI.sales@worker1",
            "help": null,
            "reason": "the node did not answer NODE_HELP within 3 s",
        });
        harness
            .inject(test_response_for(
                &forwarded,
                SYSTEM_KIND,
                "NODE_HELP_RESPONSE",
                silent.clone(),
            ))
            .await
            .expect("inject the hive's answer");
        let reply = time::timeout(Duration::from_secs(1), harness.next_outgoing())
            .await
            .expect("NODE_HELP answered by its task")
            .expect("NODE_HELP reply");
        assert_eq!(reply.meta.msg.as_deref(), Some("NODE_HELP_RESPONSE"));
        assert_eq!(reply.routing.trace_id, "help-pending");
        assert_eq!(reply.payload, silent);
    }

    /// The files an SY node keeps under nodes/SY are its own: the inventory lists it from its unit,
    /// with no managed config or state, and leaves out one this hive's role does not run.
    #[test]
    fn managed_node_inventory_lists_sy_nodes_as_core_services() {
        let state = sample_orchestrator_state_for_tests();
        let root = std::env::temp_dir().join(format!(
            "fluxbee-core-node-inventory-{}",
            Uuid::new_v4().simple()
        ));
        for name in ["SY.timer@motherbee", "SY.edge@motherbee"] {
            let dir = root.join("SY").join(name);
            std::fs::create_dir_all(&dir).expect("create sy dir");
            std::fs::write(dir.join("config.json"), "{\"tenant_id\":\"tnt:x\"}")
                .expect("write config");
        }

        let inventory =
            managed_node_inventory_with_root(&state, &root).expect("managed inventory must load");
        assert_eq!(inventory.len(), 1, "SY.edge does not run on the motherbee");
        let timer = &inventory[0];
        assert_eq!(timer["node_name"], "SY.timer@motherbee");
        assert_eq!(timer["managed"], false);
        assert_eq!(timer["inventory_source"], "core_service");
        assert_eq!(timer["config"], serde_json::json!({ "managed": false }));
        assert_eq!(timer["state"], serde_json::json!({ "managed": false }));
        assert_eq!(timer["identity"]["tenant_id"], serde_json::Value::Null);

        let _ = std::fs::remove_dir_all(&root);
    }

    /// Stage 4 (docs/ilk-tenant-model-v1.md §2.4): who launched a node comes from SY.admin's stamp;
    /// a requirement is met only by a node that matches it; a stop lasts.
    #[test]
    fn who_launched_a_node_and_what_its_caller_requires() {
        let launched = |payload: serde_json::Value| launched_by_from_payload(&payload);
        assert_eq!(
            launched(serde_json::json!({"launched_by": "cloud"})),
            "cloud"
        );
        assert_eq!(launched(serde_json::json!({})), "system");
        assert_eq!(launched(serde_json::json!({"launched_by": "  "})), "system");
        assert_eq!(
            launched(serde_json::json!({"launched_by": "x y;rm"})),
            "system"
        );
        let t = Some("tnt:a");
        assert!(node_requirements_met(None, None, None, None));
        assert!(node_requirements_met(t, Some("cloud"), t, Some("cloud")));
        assert!(!node_requirements_met(t, Some("cloud"), t, Some("archi")));
        assert!(!node_requirements_met(
            t,
            Some("cloud"),
            Some("tnt:b"),
            Some("cloud")
        ));
        assert!(
            !node_requirements_met(t, None, None, None),
            "a missing node meets nothing"
        );
        assert!(!node_requirements_met(None, Some("cloud"), t, None));
    }

    #[test]
    fn a_stop_clears_the_relaunch_and_a_start_sets_it() {
        let root =
            std::env::temp_dir().join(format!("fluxbee-relaunch-{}", Uuid::new_v4().simple()));
        std::fs::create_dir_all(&root).expect("dir");
        let path = root.join("config.json");
        std::fs::write(
            &path,
            serde_json::json!({"a": 1, "_system": {"relaunch_on_boot": true}}).to_string(),
        )
        .expect("write");
        let read = || -> serde_json::Value {
            serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap()
        };
        persist_node_relaunch_on_boot(&path, false).expect("stop");
        assert_eq!(read()["_system"]["relaunch_on_boot"], false);
        assert_eq!(read()["a"], 1);
        // The relaunches only take nodes that keep the flag.
        assert!(persisted_managed_node_from_config_value(
            "IO.x@motherbee",
            "IO",
            path.clone(),
            &serde_json::json!({"_system": {"runtime": "io.x", "runtime_version": "1", "relaunch_on_boot": false}}),
            true,
        )
        .expect("parse")
        .is_none());
        persist_node_relaunch_on_boot(&path, true).expect("start");
        assert_eq!(read()["_system"]["relaunch_on_boot"], true);
        std::fs::write(&path, "{}").expect("no system block");
        assert!(persist_node_relaunch_on_boot(&path, false).is_err());
        let _ = std::fs::remove_dir_all(&root);
    }

