    /// The template, then the request's config, then the forced `_system`; the tenant is the one
    /// the spawn resolved, over the template's and the request's (A-213: a request whose two
    /// fields name different tenants is refused before, so here they only differ in a test).
    #[test]
    fn assemble_spawn_config_map_applies_template_then_request_then_forced_system() {
        let template = serde_json::json!({
            "model": "gpt-5",
            "temperature": 0.2,
            "tenant_id": "tnt:template",
            "_system": {"managed_by": "template"}
        })
        .as_object()
        .expect("template object")
        .clone();
        let request_patch = serde_json::json!({
            "temperature": 0.9,
            "max_tokens": 4096,
            "tenant_id": "tnt:request"
        })
        .as_object()
        .expect("request object")
        .clone();
        let forced_system = serde_json::json!({
            "managed_by": "SY.orchestrator",
            "config_version": 1
        });

        let out = assemble_spawn_config_map(
            Some(template),
            request_patch,
            Some("tnt:resolved".to_string()),
            Some(forced_system.clone()),
        );

        assert_eq!(out.get("model"), Some(&serde_json::json!("gpt-5")));
        assert_eq!(out.get("temperature"), Some(&serde_json::json!(0.9)));
        assert_eq!(out.get("max_tokens"), Some(&serde_json::json!(4096)));
        assert_eq!(
            out.get("tenant_id"),
            Some(&serde_json::json!("tnt:resolved"))
        );
        assert_eq!(out.get("_system"), Some(&forced_system));
    }

    /// The resolved tenant is recorded whatever the request's config held under `tenant_id`
    /// (nothing, null, blank or padded); with none resolved, the config is left as it came.
    #[test]
    fn assemble_spawn_config_map_records_the_resolved_tenant() {
        for held in [
            None,
            Some(serde_json::Value::Null),
            Some(serde_json::json!(" ")),
            Some(serde_json::json!(" tnt:resolved ")),
            Some(serde_json::json!(7)),
        ] {
            let mut request_patch = serde_json::Map::new();
            request_patch.insert("model".to_string(), serde_json::json!("gpt-5-mini"));
            if let Some(held) = held.clone() {
                request_patch.insert("tenant_id".to_string(), held);
            }

            let out = assemble_spawn_config_map(
                None,
                request_patch.clone(),
                Some("tnt:resolved".to_string()),
                None,
            );
            assert_eq!(out.get("model"), Some(&serde_json::json!("gpt-5-mini")));
            assert_eq!(
                out.get("tenant_id"),
                Some(&serde_json::json!("tnt:resolved")),
                "{held:?}"
            );
            assert!(out.get("_system").is_none());

            let out = assemble_spawn_config_map(None, request_patch, None, None);
            assert_eq!(out.get("tenant_id"), held.as_ref(), "{held:?}");
        }
    }

    /// REGRESSION: `systemd_unit_exists` appends `.service` to the name, so passing it one that
    /// ALREADY has it asks about `<unit>.service.service`, always "not-found". That double suffix
    /// made `clear_stale_transient_unit` leave through the guard without cleaning anything, and the
    /// relaunch kept dying with "Unit ... was already loaded" on the 0.1.3 -> 0.1.4 upgrade.
    #[test]
    fn unit_names_are_not_double_suffixed() {
        // The form the real code produces, with no suffix.
        let bare = unit_from_node_name("IO.api@motherbee");
        assert!(
            !bare.ends_with(".service"),
            "unit_from_node_name must return the bare name, got {bare}"
        );
        // And if someone passes the suffixed form anyway, it must collapse to a single one.
        let suffixed = format!("{bare}.service");
        assert_eq!(suffixed.strip_suffix(".service").unwrap_or(&suffixed), bare);
    }

    /// U-10: the INTENT is persisted apart from its resolution.
    ///
    /// `fluxbee-firstboot` spawns every boot=true node with `runtime_version: "current"`. That word
    /// used to be resolved once and thrown away: only the concrete version stayed, baked into the
    /// unit's path. When a .deb upgrade replaced the runtime's directory, the path was left
    /// dangling (203/EXEC) and `restart_node` answered RUNTIME_NOT_AVAILABLE.
    #[test]
    fn system_block_keeps_the_requested_version_apart_from_the_resolved_one() {
        let system = build_node_system_block(
            "IO.api@motherbee",
            "motherbee",
            Some("io.api"),
            Some("0.1.2"),   // what it resolved to
            Some("current"), // what was asked for
            None,
            None,
            None,
            None,
            1,
        );
        assert_eq!(system["runtime_version"], serde_json::json!("0.1.2"));
        assert_eq!(
            system["requested_runtime_version"],
            serde_json::json!("current"),
            "the requester's word cannot be lost"
        );
    }

    /// Whoever names no version wanted the current one, and that is what firstboot does.
